INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0b9f34db-2979-5ab1-9fdd-470387d029a6', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 22, '<p>ඇඩ්රිනලීන් හෝර්මෝනයේ කාර්යයක් වන්නේ,</p>', '<p>ඇඩ්රිනලීන් හෝර්මෝනයේ කාර්යයක් වන්නේ,</p>', NULL, 'ඇඩ්‍රිනලින් (Adrenaline) යනු ''සටන් කිරීමේ හෝ පලායාමේ'' (Fight or flight) හෝමෝනයයි. බියක්, කෝපයක් හෝ හදිසි තත්ත්වයක් ඇති වූ විට දේහය ඊට මුහුණ දීමට සූදානම් කරන්නේ මෙමගිනි.', 'ඇඩ්‍රිනලින් (Adrenaline) යනු ''සටන් කිරීමේ හෝ පලායාමේ'' (Fight or flight) හෝමෝනයයි. බියක්, කෝපයක් හෝ හදිසි තත්ත්වයක් ඇති වූ විට දේහය ඊට මුහුණ දීමට සූදානම් කරන්නේ මෙමගිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('403c49b9-3aa1-4a3a-b0b6-49edf44b4a4e', '0b9f34db-2979-5ab1-9fdd-470387d029a6', 'හදිසි අවස්ථා සඳහා ප්‍රතිචාර දැක්වීමට දේහය සූදානම් කිරීමයි.', 'හදිසි අවස්ථා සඳහා ප්‍රතිචාර දැක්වීමට දේහය සූදානම් කිරීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b48eae74-dbb8-4e21-a4d5-8dc7529b76e9', '0b9f34db-2979-5ab1-9fdd-470387d029a6', 'දේහයේ පරිවෘත්තීය ක්‍රියාවල වේගය පාලනය කිරීමයි.', 'දේහයේ පරිවෘත්තීය ක්‍රියාවල වේගය පාලනය කිරීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e583d0e0-a84d-4d67-b394-754f09a90f3c', '0b9f34db-2979-5ab1-9fdd-470387d029a6', 'අස්ථිවල වර්ධනය උත්තේජනය කිරීමයි.', 'අස්ථිවල වර්ධනය උත්තේජනය කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ba1a939e-db9c-493e-ae6e-b07c5d131783', '0b9f34db-2979-5ab1-9fdd-470387d029a6', 'පුරුෂයින්ගේ ශුක්‍රාණු ජනනය උත්තේජනය කිරීමයි.', 'පුරුෂයින්ගේ ශුක්‍රාණු ජනනය උත්තේජනය කිරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a6c1d00c-3e66-5eff-8e75-3801c9257f36', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 23, '<p>ඔක්සිජන් 64 g ක අඩංගු $O_{2}$ මවුල ප්‍රමාණය කොපමණ ද? $(O=16)$</p>', '<p>ඔක්සිජන් 64 g ක අඩංගු $O_{2}$ මවුල ප්‍රමාණය කොපමණ ද? $(O=16)$</p>', NULL, '$O_2$ අණුවක මවුලික ස්කන්ධය $= 16 \times 2 = 32~gmol^{-1}$. එබැවින් මවුල ගණන $= 64~g / 32~gmol^{-1} = 2$ වේ.', '$O_2$ අණුවක මවුලික ස්කන්ධය $= 16 \times 2 = 32~gmol^{-1}$. එබැවින් මවුල ගණන $= 64~g / 32~gmol^{-1} = 2$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
