INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b5f21de-d7c0-43cb-a9a3-1d1330d7a75c', '359099df-e407-5262-8ace-376d1be9f9d5', 'A, B හා C යන සියල්ලමය.', 'A, B හා C යන සියල්ලමය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('56538f6a-c613-567e-b715-18522ad1d208', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 26, '<p>එක්තරා වස්තුවක චලිතයේ ප්‍රවේග - කාල ප්‍රස්තාරය දක්වා ඇත. එය මූල ලක්ෂ්‍යයෙන් ආරම්භ වී 10 s හිදී $10~ms^{-1}$ ප්‍රවේගයක් දක්වා ඒකාකාරව වැඩි වී, ඉන්පසු 20 s දක්වා නියත $10~ms^{-1}$ ප්‍රවේගයකින් ගමන් කරයි.<br>ආරම්භයේ සිට 20 s දක්වා එම වස්තුවේ විස්ථාපනය කොපමණ ද?</p>
