INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bf9e9f42-1d22-5936-bf0d-9cc997fb7f54', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 27, '<p>පහත ප්‍රකාශ සලකන්න.<br>A - රසායනික කර්මාන්ත වලදී කෙටි කාලයක් තුළ ඉහළ පලදාවක් ලබා ගැනීමට උත්ප්‍රේරක භාවිත කෙරේ.<br>B - උත්ප්‍රේරක රසායනික ප්‍රතික්‍රියාවල ශීඝ්‍රතාව වැඩි කිරීම මෙන්ම අඩු කිරීම ද සිදු කරයි.<br>ඉහත,</p>', '<p>පහත ප්‍රකාශ සලකන්න.<br>A - රසායනික කර්මාන්ත වලදී කෙටි කාලයක් තුළ ඉහළ පලදාවක් ලබා ගැනීමට උත්ප්‍රේරක භාවිත කෙරේ.<br>B - උත්ප්‍රේරක රසායනික ප්‍රතික්‍රියාවල ශීඝ්‍රතාව වැඩි කිරීම මෙන්ම අඩු කිරීම ද සිදු කරයි.<br>ඉහත,</p>', NULL, 'රසායනික කර්මාන්තවල කාර්යක්ෂමතාව වැඩි කිරීමට උත්ප්‍රේරක යොදා ගනී (A සත්‍යයි). ප්‍රතික්‍රියා ශීඝ්‍රතාව වැඩි කිරීමට ධන උත්ප්‍රේරක ද, ශීඝ්‍රතාව අඩු කිරීමට සෘණ උත්ප්‍රේරක (බාධක) ද ලෙස උත්ප්‍රේරක වර්ග දෙකක් ඇත (B සත්‍යයි).', 'රසායනික කර්මාන්තවල කාර්යක්ෂමතාව වැඩි කිරීමට උත්ප්‍රේරක යොදා ගනී (A සත්‍යයි). ප්‍රතික්‍රියා ශීඝ්‍රතාව වැඩි කිරීමට ධන උත්ප්‍රේරක ද, ශීඝ්‍රතාව අඩු කිරීමට සෘණ උත්ප්‍රේරක (බාධක) ද ලෙස උත්ප්‍රේරක වර්ග දෙකක් ඇත (B සත්‍යයි).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('feac049c-08b0-4ef0-86c9-f33958db2ded', 'bf9e9f42-1d22-5936-bf0d-9cc997fb7f54', 'A හා B ප්‍රකාශ දෙකම සත්‍ය වේ.', 'A හා B ප්‍රකාශ දෙකම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('17a3dcf7-b912-471f-a4ad-aac1225ee53c', 'bf9e9f42-1d22-5936-bf0d-9cc997fb7f54', 'A ප්‍රකාශය සත්‍ය වන අතර B ප්‍රකාශය අසත්‍ය වේ.', 'A ප්‍රකාශය සත්‍ය වන අතර B ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eb6b28bb-0d9b-408b-a40c-7d0bb2f1092b', 'bf9e9f42-1d22-5936-bf0d-9cc997fb7f54', 'A හා B ප්‍රකාශ දෙකම අසත්‍ය වේ.', 'A හා B ප්‍රකාශ දෙකම අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('287084da-6ad4-4b0a-b5fb-0833b93d98d3', 'bf9e9f42-1d22-5936-bf0d-9cc997fb7f54', 'A ප්‍රකාශය අසත්‍ය වන අතර B ප්‍රකාශය සත්‍යය වේ.', 'A ප්‍රකාශය අසත්‍ය වන අතර B ප්‍රකාශය සත්‍යය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ff65180c-b67b-53a6-b3b2-387675c00ade', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 28, '<p>නිව්ටන්ගේ තුන්වන නියමය සමග වඩාත්ම එකඟ වනුයේ පහත සඳහන් කුමන සංසිද්ධිය ද?</p>', '<p>නිව්ටන්ගේ තුන්වන නියමය සමග වඩාත්ම එකඟ වනුයේ පහත සඳහන් කුමන සංසිද්ධිය ද?</p>', NULL, 'නිව්ටන්ගේ තුන්වන නියමයෙන් කියවෙන්නේ සෑම ක්‍රියාවකටම සමාන හා ප්‍රතිවිරුද්ධ ප්‍රතික්‍රියාවක් ඇති බවයි. බෝලය පොළොවේ ගැටෙන විට පොළොව මත යොදන බලයට (ක්‍රියාව) සමාන බලයක් පොළොව මගින් බෝලය මත ඉහළට (ප්‍රතික්‍රියාව) යෙදීම නිසා එය පොළා පනියි.', 'නිව්ටන්ගේ තුන්වන නියමයෙන් කියවෙන්නේ සෑම ක්‍රියාවකටම සමාන හා ප්‍රතිවිරුද්ධ ප්‍රතික්‍රියාවක් ඇති බවයි. බෝලය පොළොවේ ගැටෙන විට පොළොව මත යොදන බලයට (ක්‍රියාව) සමාන බලයක් පොළොව මගින් බෝලය මත ඉහළට (ප්‍රතික්‍රියාව) යෙදීම නිසා එය පොළා පනියි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b886d1d6-c082-4b07-bd04-ca37d6a0f9ca', 'ff65180c-b67b-53a6-b3b2-387675c00ade', 'ඉහළ මට්ටමක සිට පතිත වන බෝලයක් පොළොවේ ගැටී ඉහළට පොළා පැනීම.', 'ඉහළ මට්ටමක සිට පතිත වන බෝලයක් පොළොවේ ගැටී ඉහළට පොළා පැනීම.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3dfa9f6d-d933-4f03-8524-db8ba2fc59d2', 'ff65180c-b67b-53a6-b3b2-387675c00ade', 'ගසකින් වැටෙන ගෙඩියක ප්‍රවේගය පොළොවට ආසන්න වත්ම උපරිම අගයට පත් වීම.', 'ගසකින් වැටෙන ගෙඩියක ප්‍රවේගය පොළොවට ආසන්න වත්ම උපරිම අගයට පත් වීම.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e110797b-e022-4f68-a785-9a7d7b7858ff', 'ff65180c-b67b-53a6-b3b2-387675c00ade', 'ධාවනය වන බස් රථයක තිරිංග හදිසියේ යෙදීමේදී මගීන් ඉදිරියට විසි වීම.', 'ධාවනය වන බස් රථයක තිරිංග හදිසියේ යෙදීමේදී මගීන් ඉදිරියට විසි වීම.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a0fe84f2-2fa8-4caa-bdf5-d25eeadda722', 'ff65180c-b67b-53a6-b3b2-387675c00ade', 'චලනය වන පාපන්දුවකට පහරදීමෙන් එහි දිශාව වෙනස් කිරීම.', 'චලනය වන පාපන්දුවකට පහරදීමෙන් එහි දිශාව වෙනස් කිරීම.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('88d46e06-e9f8-5d4e-8657-0735bc6cfcd6', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 29, '<p>ශාකයක එක් පත්‍රයක් X ද්‍රව්‍යය සහිත අවර්ණ පොලිතීන් කවරයකින් ද, තවත් පත්‍රයක් ජලීය KOH ද්‍රාවණය සහිත පොලිතීන් කවරයකින් ද ආවරණය කර ඇත.<br>මෙම ඇටවුමෙන් පරීක්ෂා කිරීමට අපේක්ෂා කරන්නේ ප්‍රභාසංශ්ලේෂණය සඳහා කුමන සාධකයක අවශ්‍යතාවද?</p>
