INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5cbdfd67-5d86-5b40-b9b7-ad18fcc5e61c', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 31, '<p>0.1 mol $dm^{-3}$ ග්ලූකෝස් ද්‍රාවණයකින් $1~dm^{3}$ ක් සාදා ගැනීමට අවශ්‍ය වන $C_{6}H_{12}O_{6}$ ස්කන්ධය කොපමණ ද? ($H=1$, $C=12$, $O=16$)</p>', '<p>0.1 mol $dm^{-3}$ ග්ලූකෝස් ද්‍රාවණයකින් $1~dm^{3}$ ක් සාදා ගැනීමට අවශ්‍ය වන $C_{6}H_{12}O_{6}$ ස්කන්ධය කොපමණ ද? ($H=1$, $C=12$, $O=16$)</p>', NULL, 'ග්ලූකෝස් ($C_6H_{12}O_6$) හි මවුලික ස්කන්ධය $= (12 \times 6) + (1 \times 12) + (16 \times 6) = 180~gmol^{-1}$. $0.1~mol~dm^{-3}$ ද්‍රාවණයකින් $1~dm^3$ ක් සෑදීමට අවශ්‍ය මවුල ගණන $= 0.1~mol$ වේ. අවශ්‍ය ස්කන්ධය $= 0.1~mol \times 180~gmol^{-1} = 18~g$.', 'ග්ලූකෝස් ($C_6H_{12}O_6$) හි මවුලික ස්කන්ධය $= (12 \times 6) + (1 \times 12) + (16 \times 6) = 180~gmol^{-1}$. $0.1~mol~dm^{-3}$ ද්‍රාවණයකින් $1~dm^3$ ක් සෑදීමට අවශ්‍ය මවුල ගණන $= 0.1~mol$ වේ. අවශ්‍ය ස්කන්ධය $= 0.1~mol \times 180~gmol^{-1} = 18~g$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
