INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('786a32f8-876c-4958-8f49-03e3f8374da1', '176ff9bc-1602-5c59-bc70-7f0533b7b473', 'වගුරු බිම් වගාබිම් බවට පත් කිරීම හා සූර්ය ශක්තියෙන් විදුලිය නිපදවීම', 'වගුරු බිම් වගාබිම් බවට පත් කිරීම හා සූර්ය ශක්තියෙන් විදුලිය නිපදවීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fd6be55e-fb18-40db-80c2-a7311d845486', '176ff9bc-1602-5c59-bc70-7f0533b7b473', 'ආහාර සැතපුම අවම කිරීම හා ඛනිජ තෙල්වලින් විදුලිය නිපදවීම', 'ආහාර සැතපුම අවම කිරීම හා ඛනිජ තෙල්වලින් විදුලිය නිපදවීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e03bb9e-4c0e-5f43-bee7-ea7d85be40bb', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 39, '<p>ඕසෝන් ස්තරය හායනය, අම්ල වැසි ඇති වීම හා සුපෝෂණය යන පාරිසරික අර්බුද කෙරෙහි බලපාන රසායනික ප්‍රභේද පිළිවෙළින් දක්වා ඇත්තේ කුමන වරණයේද?</p>', '<p>ඕසෝන් ස්තරය හායනය, අම්ල වැසි ඇති වීම හා සුපෝෂණය යන පාරිසරික අර්බුද කෙරෙහි බලපාන රසායනික ප්‍රභේද පිළිවෙළින් දක්වා ඇත්තේ කුමන වරණයේද?</p>', NULL, 'ඕසෝන් ස්තරය හායනය සඳහා ප්‍රධාන වශයෙන් ක්ලෝරොෆ්ලුවොරොකාබන (CFC) බලපායි. අම්ල වැසි ඇතිවීමට සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) වැනි වායුන් බලපායි. ජලාශ වල සුපෝෂණය ඇතිවීමට නයිට්‍රේට ($NO_3^-$) සහ පොස්පේට දායක වේ.', 'ඕසෝන් ස්තරය හායනය සඳහා ප්‍රධාන වශයෙන් ක්ලෝරොෆ්ලුවොරොකාබන (CFC) බලපායි. අම්ල වැසි ඇතිවීමට සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) වැනි වායුන් බලපායි. ජලාශ වල සුපෝෂණය ඇතිවීමට නයිට්‍රේට ($NO_3^-$) සහ පොස්පේට දායක වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
