INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec32c969-374a-442e-b4b2-9d349c7c54c2', '10ea4630-7b55-57b1-8e5b-91db488ef97d', 'දුෂ්කරතාව දරා ගැනීමට නොහැකි තත්ත්වයට පත් වූහ.', 'දුෂ්කරතාව දරා ගැනීමට නොහැකි තත්ත්වයට පත් වූහ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d50ef22-02a3-5698-8519-dc8175cdefcd', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 3, '<p>එක් එක් වාක්‍යයෙහි තද කළු අකුරෙන් මුද්‍රිත කොටසේ අර්ථයට වඩාත් සමීප අර්ථය දෙන උත්තරය තෝරන්න.<br><br>සතුරු සේනාව <b>වැල නොකැඩී</b> නගරයට ඇතුළු වූහ.</p>', '<p>එක් එක් වාක්‍යයෙහි තද කළු අකුරෙන් මුද්‍රිත කොටසේ අර්ථයට වඩාත් සමීප අර්ථය දෙන උත්තරය තෝරන්න.<br><br>සතුරු සේනාව <b>වැල නොකැඩී</b> නගරයට ඇතුළු වූහ.</p>', NULL, '''වැල නොකැඩී'' යනු එක දිගට, අතරක් නොමැතිව, එකිනෙකා පසුපසින් පැමිණීමයි.', '''වැල නොකැඩී'' යනු එක දිගට, අතරක් නොමැතිව, එකිනෙකා පසුපසින් පැමිණීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
