INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f81ef7a2-c338-50e5-be29-a6b5bd3c6e3a', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 7, '<p>සැම පදයකම අක්ෂර වින්‍යාසය නිවැරදි ව යෙදී ඇති පද පේළිය තෝරන්න.</p>', '<p>සැම පදයකම අක්ෂර වින්‍යාසය නිවැරදි ව යෙදී ඇති පද පේළිය තෝරන්න.</p>', NULL, 'තෙවන වරණයේ ඇති සියලුම පද අක්ෂර වින්‍යාස නීතිවලට අනුකූලව නිවැරදිව යෙදී ඇත. (අනෙක් ඒවායේ පරිගණක, වලාකුළු, තොටුපොළ ලෙස නිවැරදි විය යුතුය).', 'තෙවන වරණයේ ඇති සියලුම පද අක්ෂර වින්‍යාස නීතිවලට අනුකූලව නිවැරදිව යෙදී ඇත. (අනෙක් ඒවායේ පරිගණක, වලාකුළු, තොටුපොළ ලෙස නිවැරදි විය යුතුය).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('accd3d16-45d3-4b7d-bb0c-06464249bca9', 'f81ef7a2-c338-50e5-be29-a6b5bd3c6e3a', 'පරිඝණක, අරමුණ, තෘෂ්ණාව, සෝදා පාළුව', 'පරිඝණක, අරමුණ, තෘෂ්ණාව, සෝදා පාළුව', NULL, 'sanitized', 'v1', 0, 1);
