INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b44b5579-34b3-4d4c-a6b7-fdc981e8cc90', 'f81ef7a2-c338-50e5-be29-a6b5bd3c6e3a', 'පාඨමාලාව, පිළියෙළ, සන්තුෂ්ටිය, තොටු පොළ', 'පාඨමාලාව, පිළියෙළ, සන්තුෂ්ටිය, තොටු පොළ', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('66ba99f7-80df-5136-b149-856f8d4ccc15', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 8, '<p>මුදුන, ගෞරව, දීකිරි, මේඝ යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනුපිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>මුදුන, ගෞරව, දීකිරි, මේඝ යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනුපිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, '''මු'' - කෙටි පාපිල්ල, ''ගෞ'' - කොම්බුව හා ගයනුකිත්ත, ''දී'' - දීර්ඝ ඉස්පිල්ල, ''මේ'' - කොම්බුව හා දීර්ඝත්ව ලක්ෂණය (හල්කිරිම).', '''මු'' - කෙටි පාපිල්ල, ''ගෞ'' - කොම්බුව හා ගයනුකිත්ත, ''දී'' - දීර්ඝ ඉස්පිල්ල, ''මේ'' - කොම්බුව හා දීර්ඝත්ව ලක්ෂණය (හල්කිරිම).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8873482-c042-4018-ba8c-e9a3a7484f9f', '66ba99f7-80df-5136-b149-856f8d4ccc15', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය', NULL, 'sanitized', 'v1', 0, 1);
