INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('77c5a3a2-f5ea-4df8-a601-2ab3c0befa81', '66ba99f7-80df-5136-b149-856f8d4ccc15', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල', NULL, 'sanitized', 'v1', 3, 0);
