INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('95590006-b40a-4ecf-9f5f-9a31eea85289', '970289f5-aa06-5143-b505-27139e8d889f', 'පනින රිළවුන්ට ඉණිමං බැන්දා වාගේ.', 'පනින රිළවුන්ට ඉණිමං බැන්දා වාගේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b7ee69bc-f7b2-567e-a8b1-56507cb1e870', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 28, '<p>පූර්ව ස්වර ලෝප සන්ධියට හා පරස්වර ලෝප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>පූර්ව ස්වර ලෝප සන්ධියට හා පරස්වර ලෝප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, 'මැද + ඇඟිල්ල = මැදැඟිල්ල (පූර්ව ස්වර ලෝපය: ''අ'' ලොප් වේ). ඇදුරු + උතුමා = ඇදුරුතුමා (පර ස්වර ලෝපය: ''උ'' ලොප් වේ).', 'මැද + ඇඟිල්ල = මැදැඟිල්ල (පූර්ව ස්වර ලෝපය: ''අ'' ලොප් වේ). ඇදුරු + උතුමා = ඇදුරුතුමා (පර ස්වර ලෝපය: ''උ'' ලොප් වේ).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
