INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b425f0d-d3aa-4d83-b878-a9089642396a', '444b5f17-32e0-5e2a-9372-384b2e10841f', 'විකුමැත්තන් සැමවිටම නුවණැත්තන් නො වෙති.', 'විකුමැත්තන් සැමවිටම නුවණැත්තන් නො වෙති.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b4371323-5664-4534-bbb9-57a8cab75c54', '444b5f17-32e0-5e2a-9372-384b2e10841f', 'ගොවියෝ කුඹුරු සාද්දී ගෙවිලියෝ ආහාර රැගෙන යති.', 'ගොවියෝ කුඹුරු සාද්දී ගෙවිලියෝ ආහාර රැගෙන යති.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('53ae1d9c-ec5c-4966-9c77-4871fc37267a', '444b5f17-32e0-5e2a-9372-384b2e10841f', 'ප්‍රකට ගායකයෙක් වූ සනත් නන්දසිරි දක්ෂ සංගීතඥයෙක් ද විය.', 'ප්‍රකට ගායකයෙක් වූ සනත් නන්දසිරි දක්ෂ සංගීතඥයෙක් ද විය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7a8690cc-5939-5061-b400-01f82cc066a1', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 30, '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', NULL, 'රාජ්‍ය නායකයා වැනි ගෞරවාන්විත තනතුරු හැඳින්වීමේදී උක්තය ඒකවචන වුවද ඊට ගෞරවයක් වශයෙන් ආඛ්‍යාතය බහුවචනයෙන් (වෙති) තැබීම නිවැරදිය.', 'රාජ්‍ය නායකයා වැනි ගෞරවාන්විත තනතුරු හැඳින්වීමේදී උක්තය ඒකවචන වුවද ඊට ගෞරවයක් වශයෙන් ආඛ්‍යාතය බහුවචනයෙන් (වෙති) තැබීම නිවැරදිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
