INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d045303-02a3-428f-b62b-8832b723d323', '7a8690cc-5939-5061-b400-01f82cc066a1', '''රාජ්‍ය නායකයා විදේශ ගත වෙති'' යි වාර්තාකරුවෝ කීහ.', '''රාජ්‍ය නායකයා විදේශ ගත වෙති'' යි වාර්තාකරුවෝ කීහ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cfd0b260-a6cf-4265-b753-84d3a7cd0594', '7a8690cc-5939-5061-b400-01f82cc066a1', 'නිවේදකයා ද නිවේදිකාව ද වේදිකාව මතට නැග්ගා ය.', 'නිවේදකයා ද නිවේදිකාව ද වේදිකාව මතට නැග්ගා ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('34ca63d0-4031-5a5f-bb55-44a6d1811be4', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 31, '<p>ගුණපාල නිවටයකු .................. හිස නැමුවේ ය.<br>අසරණ දරුවන් .................. පිළිසරණක් වන්න.<br>වැද්දා සිය බල්ලා .................. වනයට ගියේය.<br>ආරක්ෂක අමාත්‍යාංශය රටෙහි ආරක්ෂාව .................. පිහිටුවා ඇත.<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', '<p>ගුණපාල නිවටයකු .................. හිස නැමුවේ ය.<br>අසරණ දරුවන් .................. පිළිසරණක් වන්න.<br>වැද්දා සිය බල්ලා .................. වනයට ගියේය.<br>ආරක්ෂක අමාත්‍යාංශය රටෙහි ආරක්ෂාව .................. පිහිටුවා ඇත.<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', NULL, 'අනුපිළිවෙලින්: නිවටයකු ''මෙන්'', දරුවන් ''උදෙසා/වෙනුවෙන්'', බල්ලා ''කැටුව'', ආරක්ෂාව ''උදෙසා/වෙනුවෙන්'' යෙදීම අර්ථවත් වේ.', 'අනුපිළිවෙලින්: නිවටයකු ''මෙන්'', දරුවන් ''උදෙසා/වෙනුවෙන්'', බල්ලා ''කැටුව'', ආරක්ෂාව ''උදෙසා/වෙනුවෙන්'' යෙදීම අර්ථවත් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
