INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03f07216-4db3-410c-826b-922aac1b5089', 'e119c8dd-28b1-58d3-9a15-51f026fd754f', 'සෙමින් සෙමින් ඇවිදිමින් වතුර බාල්දිය ගෙනෙන්න.', 'සෙමින් සෙමින් ඇවිදිමින් වතුර බාල්දිය ගෙනෙන්න.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('27aacf76-dc4d-5f4a-913e-488e62e1ccb0', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 33, '<p>ස්ථිරවාසීතාව යනුවෙන් හඳුන්වන්නේ,</p>', '<p>ස්ථිරවාසීතාව යනුවෙන් හඳුන්වන්නේ,</p>', NULL, 'ස්ථිරවාසීතාව යනු තැනින් තැනට යන සංචාරක දිවිය අතහැර එක් නිශ්චිත ස්ථානයක ස්ථිරවම දිගු කාලයක් පදිංචි වී සිටීමයි.', 'ස්ථිරවාසීතාව යනු තැනින් තැනට යන සංචාරක දිවිය අතහැර එක් නිශ්චිත ස්ථානයක ස්ථිරවම දිගු කාලයක් පදිංචි වී සිටීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
