INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d5e8869d-2f1a-45d4-8078-609238d8b11c', '27aacf76-dc4d-5f4a-913e-488e62e1ccb0', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජිවිතයේ දී තාවකාලික නිවාස තනා ගැනීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජිවිතයේ දී තාවකාලික නිවාස තනා ගැනීම යි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9f6fc27f-2d95-440c-93f5-ae36e1309829', '27aacf76-dc4d-5f4a-913e-488e62e1ccb0', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී එක් තැනක දිගුකලක් වාසය කිරීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී එක් තැනක දිගුකලක් වාසය කිරීම යි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a25368a5-5a54-453b-8074-b53682a9fffc', '27aacf76-dc4d-5f4a-913e-488e62e1ccb0', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් තැනින් තැන සංචාරය කරමින් ජීවත් වීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් තැනින් තැන සංචාරය කරමින් ජීවත් වීම යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3ffa6d94-52dd-5c25-a169-40db2cb12efc', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 34, '<p>පහත සඳහන් කවියේ හතරවන පදය නිවැරදිව දැක්වෙන වරණය තෝරන්න.<br><br>ලීල් නැතිව නිසරුව තෙපලන්නේ<br>මහල්ල නුඹගේ හිමි ද අසන්නේ<br>වාල් තමාවත් ඇද්ද ඉතින්නේ<br>....................................</p>', '<p>පහත සඳහන් කවියේ හතරවන පදය නිවැරදිව දැක්වෙන වරණය තෝරන්න.<br><br>ලීල් නැතිව නිසරුව තෙපලන්නේ<br>මහල්ල නුඹගේ හිමි ද අසන්නේ<br>වාල් තමාවත් ඇද්ද ඉතින්නේ<br>....................................</p>', NULL, 'සඳකිඳුරු දා කවෙහි එන මෙම පද්‍යයේ නිවැරදි අවසන් පාදය ''වාල් විඳින දුක මෙනුඹ විඳින්නේ'' යන්නයි.', 'සඳකිඳුරු දා කවෙහි එන මෙම පද්‍යයේ නිවැරදි අවසන් පාදය ''වාල් විඳින දුක මෙනුඹ විඳින්නේ'' යන්නයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fdd85e6c-acc1-4fc0-a640-a384d58c1a3f', '3ffa6d94-52dd-5c25-a169-40db2cb12efc', 'හැම කල් මළ දා දෝ සැප වන්නේ', 'හැම කල් මළ දා දෝ සැප වන්නේ', NULL, 'sanitized', 'v1', 0, 1);
