INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f3f77bdf-6dde-4cf3-8b27-3c4f64c02e9c', '3ffa6d94-52dd-5c25-a169-40db2cb12efc', 'වාල් විඳින දුක මෙනුඹ විඳින්නේ', 'වාල් විඳින දුක මෙනුඹ විඳින්නේ', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cde95503-f043-56ea-8de6-db63e243f224', 'ee9b54d1-67cc-561a-99da-9fbddb7ba42c', 35, '<p>"සාහිත්‍ය නිර්මාණයක් පරිශීලනයෙන් පසිඳුරන් මගින් පාඨක මනසට පිවිස පාඨකයාගේ භාව ප්‍රබෝධනයට හේතු වන වචන සංයෝජනය" යන්න සඳහා වඩාත් සුදුසු යෙදුම වන්නේ,</p>', '<p>"සාහිත්‍ය නිර්මාණයක් පරිශීලනයෙන් පසිඳුරන් මගින් පාඨක මනසට පිවිස පාඨකයාගේ භාව ප්‍රබෝධනයට හේතු වන වචන සංයෝජනය" යන්න සඳහා වඩාත් සුදුසු යෙදුම වන්නේ,</p>', NULL, 'ඉන්ද්‍රියයන් හරහා මනසේ චිත්ත රූප මැවීම සාහිත්‍යයේදී ''සංකල්ප රූප'' (Imagery) ලෙස හැඳින්වේ.', 'ඉන්ද්‍රියයන් හරහා මනසේ චිත්ත රූප මැවීම සාහිත්‍යයේදී ''සංකල්ප රූප'' (Imagery) ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
