INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('22f95780-417b-4732-be99-6b37d91d8e0a', '4b87f206-540b-58ba-a702-c71c58e68e2a', 'සන්තෘප්ත සහ කපා හැරෙන කලාපවල ය.', 'සන්තෘප්ත සහ කපා හැරෙන කලාපවල ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f75167c1-68cc-5098-86a8-cd6c98c2245b', 'f13bd2de-5a5e-526b-845f-6a07f6abc505', 8, '<p>නියුට්‍රෝනයක ක්වාක් සංයුතිය කුමක්ද?</p>', '<p>නියුට්‍රෝනයක ක්වාක් සංයුතිය කුමක්ද?</p>', NULL, 'නියුට්‍රෝනයක් (Neutron) සෑදී ඇත්තේ එක් ''up'' ($u$) ක්වාක් එකකින් සහ ''down'' ($d$) ක්වාක් දෙකකිනි. එබැවින් එහි ක්වාක් සංයුතිය $udd$ වේ. (ප්‍රෝටෝනයක නම් එය $uud$ වේ).', 'නියුට්‍රෝනයක් (Neutron) සෑදී ඇත්තේ එක් ''up'' ($u$) ක්වාක් එකකින් සහ ''down'' ($d$) ක්වාක් දෙකකිනි. එබැවින් එහි ක්වාක් සංයුතිය $udd$ වේ. (ප්‍රෝටෝනයක නම් එය $uud$ වේ).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
