INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92213dbe-13a4-478f-8148-2efa32d01856', 'bb4a2330-5584-5f42-a354-175af72920c9', '$\sqrt{\frac{r_{1}}{r_{2}}}$', '$\sqrt{\frac{r_{1}}{r_{2}}}$', NULL, 'sanitized', 'v1', 3, 0);
