INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b4ea214d-d5a7-4c71-b38b-cc777b62aeb2', '78734430-12df-5f83-8ae9-a4bed50c29aa', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('44f253a2-441f-57bd-abbc-83a715fed9f4', 'f13bd2de-5a5e-526b-845f-6a07f6abc505', 26, '<p>අභ්‍යන්තර අරය $a$ සහ දිග $l$ වන තිරස් නළයක් හරහා $\Delta p$ පීඩන අන්තරයකට යටත්ව ගලන දුස්ස්‍රාවිතා සංගුණකය $\eta$ වන ද්‍රවයක වේගය $v$, $v=\frac{Ca^{n}\Delta p}{\eta l}$ ලෙස ලිවිය හැක. මෙහි $C$ යනු මාන නොමැති නියතයකි. $n$ හි අගය කොපමණ ද?</p>', '<p>අභ්‍යන්තර අරය $a$ සහ දිග $l$ වන තිරස් නළයක් හරහා $\Delta p$ පීඩන අන්තරයකට යටත්ව ගලන දුස්ස්‍රාවිතා සංගුණකය $\eta$ වන ද්‍රවයක වේගය $v$, $v=\frac{Ca^{n}\Delta p}{\eta l}$ ලෙස ලිවිය හැක. මෙහි $C$ යනු මාන නොමැති නියතයකි. $n$ හි අගය කොපමණ ද?</p>', NULL, 'මාන විශ්ලේෂණය (Dimensional Analysis) භාවිතයෙන්:<br>වේගයේ ($v$) මාන = $L T^{-1}$<br>පීඩනයේ ($\Delta p$) මාන = $M L^{-1} T^{-2}$<br>දුස්ස්‍රාවිතා සංගුණකයේ ($\eta$) මාන = $M L^{-1} T^{-1}$<br>අරයේ ($a$) සහ දිගෙහි ($l$) මාන = $L$<br><br>සමීකරණයට ආදේශ කිරීමෙන්:<br>$L T^{-1} = \frac{L^n \cdot (M L^{-1} T^{-2})}{(M L^{-1} T^{-1}) \cdot L}$<br>$L T^{-1} = \frac{L^n \cdot T^{-1}}{L} = L^{n-1} T^{-1}$<br><br>දෙපස $L$ හි දර්ශක සමාන කිරීමෙන්: $1 = n - 1 \Rightarrow n = 2$.', 'මාන විශ්ලේෂණය (Dimensional Analysis) භාවිතයෙන්:<br>වේගයේ ($v$) මාන = $L T^{-1}$<br>පීඩනයේ ($\Delta p$) මාන = $M L^{-1} T^{-2}$<br>දුස්ස්‍රාවිතා සංගුණකයේ ($\eta$) මාන = $M L^{-1} T^{-1}$<br>අරයේ ($a$) සහ දිගෙහි ($l$) මාන = $L$<br><br>සමීකරණයට ආදේශ කිරීමෙන්:<br>$L T^{-1} = \frac{L^n \cdot (M L^{-1} T^{-2})}{(M L^{-1} T^{-1}) \cdot L}$<br>$L T^{-1} = \frac{L^n \cdot T^{-1}}{L} = L^{n-1} T^{-1}$<br><br>දෙපස $L$ හි දර්ශක සමාන කිරීමෙන්: $1 = n - 1 \Rightarrow n = 2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
