INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d8d993a0-9185-549f-8f53-8da26a281cd5', 'f13bd2de-5a5e-526b-845f-6a07f6abc505', 33, '<p>සමාන්තර සන්නායක තහඩු දෙකක් හරහා වෝල්ටීයතාවක් යොදා ඇත. ස්කන්ධ පිළිවෙළින් $2m$ සහ $m$ වන $X$ සහ $Y$ ආරෝපිත බිඳිති දෙකක් රූපයේ පෙන්වා ඇති අයුරින් තහඩු අතර නිසලව ඇත. $X$ සහ $Y$ අතර ඇති අන්තර් ක්‍රියාව නොසලකා හරින්න. තහඩු දෙක එකිනෙකට සමීප කරන විට<br><br></p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9a1c49b9-cff4-4e9f-aa45-397f33ddfa99', 'd8d993a0-9185-549f-8f53-8da26a281cd5', '$X$ සහ $Y$ සමතුලිතතාවයේම පවතී.', '$X$ සහ $Y$ සමතුලිතතාවයේම පවතී.', NULL, 'sanitized', 'v1', 0, 1);
