INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4ae5411c-e147-4f98-919c-97a18d483ef6', 'd8d993a0-9185-549f-8f53-8da26a281cd5', '$Y$ ට වඩා වැඩි ත්වරණයකින් $X$ ඉහළට නගී.', '$Y$ ට වඩා වැඩි ත්වරණයකින් $X$ ඉහළට නගී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('74addd3a-aab2-4d29-b302-eb7cd27e1cce', 'd8d993a0-9185-549f-8f53-8da26a281cd5', '$Y$ ට වඩා වැඩි ත්වරණයකින් $X$ පහළට වැටේ.', '$Y$ ට වඩා වැඩි ත්වරණයකින් $X$ පහළට වැටේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aa5f8645-ba4a-5188-a2bb-4d8323c52054', 'f13bd2de-5a5e-526b-845f-6a07f6abc505', 34, '<p>පටු නළයක දෙකෙළවරෙහි $A$ සහ $B$ සබන් බුබුළු දෙකක් පිහිටුවා ඇත. ආරම්භයේදී නළය මැද ඇති කරාමය වසා ඇති අතර $A$ බුබුලේ අරය $B$ හි අරයට වඩා අඩු ය. ඊට පසු කරාමය විවෘත කර බුබුළු නොකැඩී පද්ධතිය සමතුලිතතාවය කරා ළඟා වීමට ඉඩ හරිනු ලැබේ. බුබුළුවල අවසාන අරයන් ($R_A, R_B$) සහ අවසාන පරිමා ($V_A, V_B$) අතර සම්බන්ධය කුමක්ද?<br><br></p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0dd80951-127e-434e-ae82-090bdcbbfe34', 'aa5f8645-ba4a-5188-a2bb-4d8323c52054', '$R_A < R_B,\ V_A < V_B$', '$R_A < R_B,\ V_A < V_B$', NULL, 'sanitized', 'v1', 0, 1);
