INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('99fac047-4a3d-4114-bffc-ac48a05524bd', '8e341136-a550-548a-8a59-096a0d81d5b3', '$\frac{V(\beta-\rho)g L}{A}(Y_1+Y_2)$', '$\frac{V(\beta-\rho)g L}{A}(Y_1+Y_2)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5eb03ec2-1d3d-5619-a6d4-05e818f9e30c', 'f13bd2de-5a5e-526b-845f-6a07f6abc505', 38, '<p>එකක් උඩ එකක් තබා ඇති ඝනකම් පාරදෘශ්‍ය සමාන්තර තහඩු හතරක් රූපයේ පෙන්වා ඇත. තහඩු සාදා ඇති ද්‍රව්‍යයන්ගේ වර්තනාංක පිළිවෙළින් $n_1, n_2, n_3$ සහ $n_4$ වේ. පළමු තහඩුවේ සහ දෙවන තහඩුවේ අතුරු මුහුණතේදී ඒක වර්ණ ආලෝක කිරණයක් පෙන්වා ඇති පරිදි $\\theta$ පතන කෝණයකින් පතිත වේ. කිරණය තුන්වන සහ හතරවන තහඩු වල අතුරු මුහුණත ඔස්සේ යෑමට නම් $\\theta$ ට තිබිය යුතු අගය කුමක්ද?<br><br></p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a7babb73-bdac-451f-91c6-a6cff775688c', '5eb03ec2-1d3d-5619-a6d4-05e818f9e30c', '$\theta=\sin^{-1}\left(\frac{n_4}{n_1}\right)$', '$\theta=\sin^{-1}\left(\frac{n_4}{n_1}\right)$', NULL, 'sanitized', 'v1', 0, 1);
