INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f7ae2d3-c33f-4b51-9e35-7afc7133e3de', '790370d1-3f75-5a50-b7ac-ae0dd76e63e1', '$Q = \frac{\sigma(T_1^4 - T_2^4)}{(\frac{1}{e_1} + \frac{1}{e_2})}$', '$Q = \frac{\sigma(T_1^4 - T_2^4)}{(\frac{1}{e_1} + \frac{1}{e_2})}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('731c459f-8edf-4eda-a62b-69234c6c3ce1', '790370d1-3f75-5a50-b7ac-ae0dd76e63e1', '$Q = \frac{\sigma(T_1 - T_2)^4}{(\frac{1}{e_1} + \frac{1}{e_2} - 1)}$', '$Q = \frac{\sigma(T_1 - T_2)^4}{(\frac{1}{e_1} + \frac{1}{e_2} - 1)}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('da9c99d5-6dda-5918-8f77-ddbf7745b7de', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 5, '<p>දිලිසෙන රිදී පෘෂ්ඨයක සාපේක්ෂ විමෝචකතාවය (Relative Emissivity) සාමාන්‍යයෙන් කෙසේ අගයක් ගනීද?</p>', '<p>දිලිසෙන රිදී පෘෂ්ඨයක සාපේක්ෂ විමෝචකතාවය (Relative Emissivity) සාමාන්‍යයෙන් කෙසේ අගයක් ගනීද?</p>', NULL, 'දිලිසෙන රිදී පෘෂ්ඨයක් (Shiny Silver Surface) යනු ඉතා හොඳ පරාවර්තකයකි.<br>කර්චොෆ්ගේ විකිරණ නියමයට (Kirchhoff''s Law of Thermal Radiation) අනුව, හොඳ පරාවර්තක යනු දුර්වල විමෝචක වේ.<br>පූර්ණ කෘෂ්ණ වස්තුවක විමෝචකතාව $1$ වන අතර, රිදී පෘෂ්ඨයක සාපේක්ෂ විමෝචකතාව ($e$) $0$ ට ඉතා ආසන්න කුඩා ධන අගයක් ගනී.', 'දිලිසෙන රිදී පෘෂ්ඨයක් (Shiny Silver Surface) යනු ඉතා හොඳ පරාවර්තකයකි.<br>කර්චොෆ්ගේ විකිරණ නියමයට (Kirchhoff''s Law of Thermal Radiation) අනුව, හොඳ පරාවර්තක යනු දුර්වල විමෝචක වේ.<br>පූර්ණ කෘෂ්ණ වස්තුවක විමෝචකතාව $1$ වන අතර, රිදී පෘෂ්ඨයක සාපේක්ෂ විමෝචකතාව ($e$) $0$ ට ඉතා ආසන්න කුඩා ධන අගයක් ගනී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
