INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b402de1e-ad0b-4920-af10-6defb9760b12', 'da9c99d5-6dda-5918-8f77-ddbf7745b7de', 'සෘණ අගයක් ගනී', 'සෘණ අගයක් ගනී', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a52cd3e9-8a1c-5e4a-ae94-2f51dda70427', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 6, '<p>සුමට සමතල පෘෂ්ඨයක් මත $2v$ ප්‍රවේගයෙන් චලනය වන ස්කන්ධය $M$ වන කුට්ටියක්, එම දිශාවට $v$ ප්‍රවේගයෙන් චලනය වන ස්කන්ධය $M$ වූ වෙනත් කුට්ටියක් හා පූර්ණ අප්‍රත්‍යස්ථ ගැටුමක් සිදු කරයි. ගැටුමෙන් පසු පළමු කුට්ටියේ ප්‍රවේගය කොපමණ ද?</p>', '<p>සුමට සමතල පෘෂ්ඨයක් මත $2v$ ප්‍රවේගයෙන් චලනය වන ස්කන්ධය $M$ වන කුට්ටියක්, එම දිශාවට $v$ ප්‍රවේගයෙන් චලනය වන ස්කන්ධය $M$ වූ වෙනත් කුට්ටියක් හා පූර්ණ අප්‍රත්‍යස්ථ ගැටුමක් සිදු කරයි. ගැටුමෙන් පසු පළමු කුට්ටියේ ප්‍රවේගය කොපමණ ද?</p>', NULL, 'ගම්‍යතා සංස්ථිති නියමයට අනුව, ගැටුමට පෙර මුළු ගම්‍යතාවය ගැටුමට පසු මුළු ගම්‍යතාවයට සමාන වේ.<br>ගැටුමට පෙර ගම්‍යතාවය $= M(2v) + M(v) = 3Mv$<br>පූර්ණ අප්‍රත්‍යස්ථ ගැටුමකදී කුට්ටි දෙක එකට බැඳී ගමන් කරයි. එබැවින් අවසාන ස්කන්ධය $= 2M$ වේ.<br>අවසාන ප්‍රවේගය $V$ නම්,<br>$$2M \cdot V = 3Mv$$<br>$$V = \frac{3}{2}v$$<br>එමනිසා පළමු කුට්ටියේ මෙන්ම දෙවන කුට්ටියේද අවසාන ප්‍රවේගය $\frac{3}{2}v$ වේ.', 'ගම්‍යතා සංස්ථිති නියමයට අනුව, ගැටුමට පෙර මුළු ගම්‍යතාවය ගැටුමට පසු මුළු ගම්‍යතාවයට සමාන වේ.<br>ගැටුමට පෙර ගම්‍යතාවය $= M(2v) + M(v) = 3Mv$<br>පූර්ණ අප්‍රත්‍යස්ථ ගැටුමකදී කුට්ටි දෙක එකට බැඳී ගමන් කරයි. එබැවින් අවසාන ස්කන්ධය $= 2M$ වේ.<br>අවසාන ප්‍රවේගය $V$ නම්,<br>$$2M \cdot V = 3Mv$$<br>$$V = \frac{3}{2}v$$<br>එමනිසා පළමු කුට්ටියේ මෙන්ම දෙවන කුට්ටියේද අවසාන ප්‍රවේගය $\frac{3}{2}v$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
