INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e0009665-cb49-41a7-9e88-1f1c67a19ee9', '0b21a117-9ec7-589e-b2fd-72308c95f460', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e784c8db-0344-501b-abf3-06af665a7f76', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 16, '<p>හරස්කඩ වර්ග ඵලය $A$ වූ තිරස් බටයක් තුළින් $3v$ වේගයෙන් ගලා යන්නා වූ ඝනත්වය $\rho$ වන ද්‍රවයක් සිරස් බිත්තියකට ලම්බකව ගැටී, පොළා පැනීමකින් තොරව බිත්තිය දිගේ පහළට ගලා යයි. ද්‍රවය මගින් බිත්තිය මත ඇති කරනු ලබන බලය වන්නේ,</p>', '<p>හරස්කඩ වර්ග ඵලය $A$ වූ තිරස් බටයක් තුළින් $3v$ වේගයෙන් ගලා යන්නා වූ ඝනත්වය $\rho$ වන ද්‍රවයක් සිරස් බිත්තියකට ලම්බකව ගැටී, පොළා පැනීමකින් තොරව බිත්තිය දිගේ පහළට ගලා යයි. ද්‍රවය මගින් බිත්තිය මත ඇති කරනු ලබන බලය වන්නේ,</p>', NULL, 'ද්‍රවයේ ස්කන්ධ ගලායාමේ ශීඝ්‍රතාවය (Mass flow rate) $= A \cdot (3v) \cdot \rho = 3A\rho v$<br>ද්‍රවය බිත්තියේ ගැටී පොළා නොපැන පහළට ගලා යන බැවින්, තිරස් දිශාවට ප්‍රවේගයේ වෙනස $= 3v - 0 = 3v$<br>නිව්ටන්ගේ දෙවන නියමයට අනුව බලය $=$ ගම්‍යතා වෙනස් වීමේ ශීඝ්‍රතාවය<br>$$F = (3A\rho v) \times (3v) = 9\rho A v^{2}$$', 'ද්‍රවයේ ස්කන්ධ ගලායාමේ ශීඝ්‍රතාවය (Mass flow rate) $= A \cdot (3v) \cdot \rho = 3A\rho v$<br>ද්‍රවය බිත්තියේ ගැටී පොළා නොපැන පහළට ගලා යන බැවින්, තිරස් දිශාවට ප්‍රවේගයේ වෙනස $= 3v - 0 = 3v$<br>නිව්ටන්ගේ දෙවන නියමයට අනුව බලය $=$ ගම්‍යතා වෙනස් වීමේ ශීඝ්‍රතාවය<br>$$F = (3A\rho v) \times (3v) = 9\rho A v^{2}$$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
