INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('26600a64-5af6-5b15-af9f-cc5601d4979a', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 17, '<p>රූපයේ පෙන්වා ඇති පරිදි $+4q$ හා $-q$ වූ ලක්ෂ්‍යයීය ආරෝපණ දෙකක් $x$ දුරක පරතරයකින් අචලව තබා ඇත. එම ආරෝපණ දෙක යා කරන රේඛාවේ $-q$ හි සිට $y$ දුරකින් තබන ලද වෙනත් $+q$ ආරෝපණයක් මත සඵල විද්‍යුත් බලයක් ඇති නොවේ. $x$ හා $y$ අතර සම්බන්ධය දෙනු ලබන්නේ,</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('35ce0714-35f6-4547-bee4-d2d72da4c1fd', '26600a64-5af6-5b15-af9f-cc5601d4979a', '$x = y$ මගිනි.', '$x = y$ මගිනි.', NULL, 'sanitized', 'v1', 0, 1);
