INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b20df783-1fc2-4092-af2e-6765c2c6ec6b', '25403425-6c7d-52c2-aaee-f1cb3e4e11e1', '(B) සහ (C) පමණක් සත්‍ය වේ.', '(B) සහ (C) පමණක් සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c74c8af5-59d1-49ed-8ab1-83e8b69510a0', '25403425-6c7d-52c2-aaee-f1cb3e4e11e1', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('075864bf-c864-5836-82b0-3656175e315c', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 28, '<p>යුරේනියම් න්‍යෂ්ටියකට, ලැසි නියුට්‍රෝනයකින් ($n$) පහර දුන් විට (බැට දුන් විට) පහත සඳහන් න්‍යෂ්ටික ප්‍රතික්‍රියාව සිදු විය හැක.<br>$$^{235}_{92}U + ^{1}_{0}n \longrightarrow ^{102}_{44}X + ^{131}_{a}Y + b ^{1}_{0}n$$<br>මෙහි $a$ සහ $b$ හි අගයන් පිළිවෙළින් වන්නේ,</p>', '<p>යුරේනියම් න්‍යෂ්ටියකට, ලැසි නියුට්‍රෝනයකින් ($n$) පහර දුන් විට (බැට දුන් විට) පහත සඳහන් න්‍යෂ්ටික ප්‍රතික්‍රියාව සිදු විය හැක.<br>$$^{235}_{92}U + ^{1}_{0}n \longrightarrow ^{102}_{44}X + ^{131}_{a}Y + b ^{1}_{0}n$$<br>මෙහි $a$ සහ $b$ හි අගයන් පිළිවෙළින් වන්නේ,</p>', NULL, 'න්‍යෂ්ටික ප්‍රතික්‍රියාවකදී පරමාණුක ක්‍රමාංකය (Z) සහ ස්කන්ධ ක්‍රමාංකය (A) සංස්ථාපනය විය යුතුය.<br>පරමාණුක ක්‍රමාංක සංස්ථිතිය: $92 + 0 = 44 + a + b(0) \implies a = 92 - 44 = 48$<br>ස්කන්ධ ක්‍රමාංක සංස්ථිතිය: $235 + 1 = 102 + 131 + b \implies 236 = 233 + b \implies b = 3$', 'න්‍යෂ්ටික ප්‍රතික්‍රියාවකදී පරමාණුක ක්‍රමාංකය (Z) සහ ස්කන්ධ ක්‍රමාංකය (A) සංස්ථාපනය විය යුතුය.<br>පරමාණුක ක්‍රමාංක සංස්ථිතිය: $92 + 0 = 44 + a + b(0) \implies a = 92 - 44 = 48$<br>ස්කන්ධ ක්‍රමාංක සංස්ථිතිය: $235 + 1 = 102 + 131 + b \implies 236 = 233 + b \implies b = 3$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
