INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9689d379-3e69-482b-bc3c-ad2758f78a75', '651eb945-b4a7-5e6d-a97f-1f0aebd0a62f', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ca5cd450-ce89-5021-be34-d66d31a195a5', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 30, '<p>රූපයේ දක්වා ඇති පරිදි හොඳින් පරිවරණය කරන ලද භාජනයක් තුළ ඝර්ෂණය රහිත පිස්ටනයක් මගින් වාතය සිරකර ඇත.<br>ප්‍රතිරෝධය $100\\,\\Omega$ වන දඟරයක් තුළින් $1\\text{ A}$ ධාරාවක් මිනිත්තු 5ක කාලයක් යැවීම මගින් වාතය රත් කරන ලදී.<br>තාපන ක්‍රියාවලියේදී වාත පරිමාව $0.4\\text{ m}^{3}$ සිට $0.5\\text{ m}^{3}$ දක්වා $150\\text{ kPa}$ නියත පීඩනයකදී ප්‍රසාරණය විය. වාතයෙහි අභ්‍යන්තර ශක්ති වෙනස වන්නේ,</p>
