INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a0696e8-2b28-48dd-8ffa-db9e9429079d', 'd7aaa5aa-8df4-570c-8727-812dfc8274c7', 'තරංගයේ තීව්‍රතාවය', 'තරංගයේ තීව්‍රතාවය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a63b2b63-ce18-5acc-b2bf-d46aa3f3c97d', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 44, '<p>පහත දැක්වෙන ප්‍රකාශ අතුරින් ප්‍රකාශ විද්‍යුත් ආචරණය (Photoelectric effect) සඳහා වඩාත් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>පහත දැක්වෙන ප්‍රකාශ අතුරින් ප්‍රකාශ විද්‍යුත් ආචරණය (Photoelectric effect) සඳහා වඩාත් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'අයින්ස්ටයින්ගේ ප්‍රකාශ විද්‍යුත් සමීකරණයට අනුව, $K_{max} = hf - \Phi$ වේ. මෙහි $f$ යනු පතන ආලෝකයේ සංඛ්‍යාතය සහ $\Phi$ යනු කාර්ය ශ්‍රිතයයි.<br>මේ අනුව ආලෝකයේ සංඛ්‍යාතය වැඩි කරන විට විමෝචනය වන ප්‍රකාශ ඉලෙක්ට්‍රෝනවල උපරිම චාලක ශක්තිය රේඛීයව වැඩි වේ.<br>ආලෝකයේ තීව්‍රතාවය වැඩි කිරීමෙන් සිදුවන්නේ තත්පරයකට විමෝචනය වන ඉලෙක්ට්‍රෝන සංඛ්‍යාව (ප්‍රකාශ ධාරාව) වැඩි වීමයි.', 'අයින්ස්ටයින්ගේ ප්‍රකාශ විද්‍යුත් සමීකරණයට අනුව, $K_{max} = hf - \Phi$ වේ. මෙහි $f$ යනු පතන ආලෝකයේ සංඛ්‍යාතය සහ $\Phi$ යනු කාර්ය ශ්‍රිතයයි.<br>මේ අනුව ආලෝකයේ සංඛ්‍යාතය වැඩි කරන විට විමෝචනය වන ප්‍රකාශ ඉලෙක්ට්‍රෝනවල උපරිම චාලක ශක්තිය රේඛීයව වැඩි වේ.<br>ආලෝකයේ තීව්‍රතාවය වැඩි කිරීමෙන් සිදුවන්නේ තත්පරයකට විමෝචනය වන ඉලෙක්ට්‍රෝන සංඛ්‍යාව (ප්‍රකාශ ධාරාව) වැඩි වීමයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('26035d86-028e-4d72-b5bf-71d1dd6e6f3d', 'a63b2b63-ce18-5acc-b2bf-d46aa3f3c97d', 'ආලෝකයේ තීව්‍රතාව වැඩි කරන විට විමෝචනය වන ඉලෙක්ට්‍රෝන වල උපරිම චාලක ශක්තිය වැඩි වේ.', 'ආලෝකයේ තීව්‍රතාව වැඩි කරන විට විමෝචනය වන ඉලෙක්ට්‍රෝන වල උපරිම චාලක ශක්තිය වැඩි වේ.', NULL, 'sanitized', 'v1', 0, 1);
