INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0072ed7e-8604-4312-b194-46d0eaed42b1', 'a63b2b63-ce18-5acc-b2bf-d46aa3f3c97d', 'සියලුම සංඛ්‍යාත සඳහා ඉලෙක්ට්‍රෝන විමෝචනය සිදු වේ.', 'සියලුම සංඛ්‍යාත සඳහා ඉලෙක්ට්‍රෝන විමෝචනය සිදු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fad75a5f-8aea-4327-83d4-0f30045e47a9', 'a63b2b63-ce18-5acc-b2bf-d46aa3f3c97d', 'විමෝචනය වන ඉලෙක්ට්‍රෝන සංඛ්‍යාව ආලෝකයේ සංඛ්‍යාතය මත පමණක් රඳා පවතී.', 'විමෝචනය වන ඉලෙක්ට්‍රෝන සංඛ්‍යාව ආලෝකයේ සංඛ්‍යාතය මත පමණක් රඳා පවතී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('576355c8-c906-4907-9422-c5559e964575', 'a63b2b63-ce18-5acc-b2bf-d46aa3f3c97d', 'එය ආලෝකයේ තරංග ස්වභාවය මැනවින් තහවුරු කරයි.', 'එය ආලෝකයේ තරංග ස්වභාවය මැනවින් තහවුරු කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('66172c9d-a0dd-5cbb-a972-bf4b09f0a08c', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 45, '<p>$R$ අරයක් සහිත ඒකාකාර ඝන ගෝලයක කේන්ද්‍රයේ සිට $r$ දුරකින් වූ ලක්ෂ්‍යයක ගුරුත්වාකර්ෂණ ක්ෂේත්‍ර තීව්‍රතාව ($g$) විචලනය වන ආකාරය ($r < R$ සඳහා) දක්වන්නේ කුමන සම්බන්ධතාවය මගින්ද?</p>', '<p>$R$ අරයක් සහිත ඒකාකාර ඝන ගෝලයක කේන්ද්‍රයේ සිට $r$ දුරකින් වූ ලක්ෂ්‍යයක ගුරුත්වාකර්ෂණ ක්ෂේත්‍ර තීව්‍රතාව ($g$) විචලනය වන ආකාරය ($r < R$ සඳහා) දක්වන්නේ කුමන සම්බන්ධතාවය මගින්ද?</p>', NULL, 'ඒකාකාර ඝන ගෝලයක් තුළ ($r < R$) ගුරුත්වාකර්ෂණ ක්ෂේත්‍ර තීව්‍රතාවය $g = \frac{GMr}{R^3}$ මගින් දෙනු ලැබේ.<br>මෙම සමීකරණයට අනුව, ගෝලය තුළ $g$ හි අගය කේන්ද්‍රයේ සිට ඇති දුරට ($r$) අනුලෝමව සමානුපාතික වේ. එනම් $g \propto r$ වේ.', 'ඒකාකාර ඝන ගෝලයක් තුළ ($r < R$) ගුරුත්වාකර්ෂණ ක්ෂේත්‍ර තීව්‍රතාවය $g = \frac{GMr}{R^3}$ මගින් දෙනු ලැබේ.<br>මෙම සමීකරණයට අනුව, ගෝලය තුළ $g$ හි අගය කේන්ද්‍රයේ සිට ඇති දුරට ($r$) අනුලෝමව සමානුපාතික වේ. එනම් $g \propto r$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
