INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d7d0e799-5bce-46a0-9bb5-7480d89853d7', '66172c9d-a0dd-5cbb-a972-bf4b09f0a08c', '$g \propto \frac{1}{r}$', '$g \propto \frac{1}{r}$', NULL, 'sanitized', 'v1', 1, 0);
