INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6ba9fcf7-8a4a-57d4-a3c7-be694c8a7e2c', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 46, '<p>දිග $L$ සහ හරස්කඩ වර්ගඵලය $A$ වූ සිලින්ඩරාකාර කම්බියක ප්‍රතිරෝධය $R$ වේ. එය ඇද එහි දිග $2L$ බවට පත් කළ විට, එහි නව ප්‍රතිරෝධය කොපමණ ද? (පරිමාව නියත යැයි උපකල්පනය කරන්න)</p>', '<p>දිග $L$ සහ හරස්කඩ වර්ගඵලය $A$ වූ සිලින්ඩරාකාර කම්බියක ප්‍රතිරෝධය $R$ වේ. එය ඇද එහි දිග $2L$ බවට පත් කළ විට, එහි නව ප්‍රතිරෝධය කොපමණ ද? (පරිමාව නියත යැයි උපකල්පනය කරන්න)</p>', NULL, 'කම්බියේ ආරම්භක ප්‍රතිරෝධය $R = \frac{\rho L}{A}$.<br>පරිමාව නියත බැවින් $A \cdot L = A'' \cdot (2L) \implies A'' = \frac{A}{2}$ වේ.<br>නව ප්‍රතිරෝධය $R'' = \frac{\rho (2L)}{A''} = \frac{\rho (2L)}{A/2} = 4 \frac{\rho L}{A} = 4R$.<br>එමනිසා නව ප්‍රතිරෝධය ආරම්භක අගය මෙන් සිව් ගුණයක් වේ.', 'කම්බියේ ආරම්භක ප්‍රතිරෝධය $R = \frac{\rho L}{A}$.<br>පරිමාව නියත බැවින් $A \cdot L = A'' \cdot (2L) \implies A'' = \frac{A}{2}$ වේ.<br>නව ප්‍රතිරෝධය $R'' = \frac{\rho (2L)}{A''} = \frac{\rho (2L)}{A/2} = 4 \frac{\rho L}{A} = 4R$.<br>එමනිසා නව ප්‍රතිරෝධය ආරම්භක අගය මෙන් සිව් ගුණයක් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
