INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('32da8072-91d3-56c3-91c1-839d26093c67', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 48, '<p>පරිපූර්ණ වායුවක් සමෝෂ්ණ (Isothermal) ප්‍රසාරණයකට ලක් කිරීමේදී, පද්ධතිය මගින් කරන ලද කාර්යය ($W$), සපයන ලද තාපය ($Q$) සහ අභ්‍යන්තර ශක්ති වෙනස ($\Delta U$) අතර සම්බන්ධය වන්නේ,</p>', '<p>පරිපූර්ණ වායුවක් සමෝෂ්ණ (Isothermal) ප්‍රසාරණයකට ලක් කිරීමේදී, පද්ධතිය මගින් කරන ලද කාර්යය ($W$), සපයන ලද තාපය ($Q$) සහ අභ්‍යන්තර ශක්ති වෙනස ($\Delta U$) අතර සම්බන්ධය වන්නේ,</p>', NULL, 'සමෝෂ්ණ ක්‍රියාවලියකදී (Isothermal process) පරිපූර්ණ වායුවක උෂ්ණත්වය නියතව පවතී. පරිපූර්ණ වායුවක අභ්‍යන්තර ශක්තිය රඳා පවතින්නේ උෂ්ණත්වය මත පමණක් බැවින්, අභ්‍යන්තර ශක්ති වෙනස $\Delta U = 0$ වේ.<br>තාපගති විද්‍යාවේ පළමු නියමයට ($Q = \Delta U + W$) අනුව, $\Delta U = 0$ බැවින් $Q = W$ වේ. එනම් සපයන ලද මුළු තාපය වායුව මගින් කරන ලද කාර්යයට සමාන වේ.', 'සමෝෂ්ණ ක්‍රියාවලියකදී (Isothermal process) පරිපූර්ණ වායුවක උෂ්ණත්වය නියතව පවතී. පරිපූර්ණ වායුවක අභ්‍යන්තර ශක්තිය රඳා පවතින්නේ උෂ්ණත්වය මත පමණක් බැවින්, අභ්‍යන්තර ශක්ති වෙනස $\Delta U = 0$ වේ.<br>තාපගති විද්‍යාවේ පළමු නියමයට ($Q = \Delta U + W$) අනුව, $\Delta U = 0$ බැවින් $Q = W$ වේ. එනම් සපයන ලද මුළු තාපය වායුව මගින් කරන ලද කාර්යයට සමාන වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0cf41057-5e1a-4917-9744-d5284e0490b0', '32da8072-91d3-56c3-91c1-839d26093c67', '$Q = W$ සහ $\Delta U = 0$', '$Q = W$ සහ $\Delta U = 0$', NULL, 'sanitized', 'v1', 0, 1);
