INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2837154b-819c-4970-9898-ca1f54e3907b', '713e4ac7-b17c-58a5-b81d-984845ca1ab4', 'දුස්‍රාවී බලයට සමාන වේ.', 'දුස්‍රාවී බලයට සමාන වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0af66eb2-60d5-4047-9dca-992936b2f2f5', '713e4ac7-b17c-58a5-b81d-984845ca1ab4', 'බර හා උඩුකුරු තෙරපුමේ ඓක්‍යයට සමාන වේ.', 'බර හා උඩුකුරු තෙරපුමේ ඓක්‍යයට සමාන වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('161a28e0-51ce-5c9a-8d01-c1bc129bba58', 'f55c78e7-09e5-5c78-a243-71d4965c3c96', 50, '<p>චුම්බක ස්‍රාවයේ (Magnetic Flux) ජාත්‍යන්තර සම්මත (SI) ඒකකය කුමක්ද?</p>', '<p>චුම්බක ස්‍රාවයේ (Magnetic Flux) ජාත්‍යන්තර සම්මත (SI) ඒකකය කුමක්ද?</p>', NULL, 'චුම්බක ස්‍රාවයේ (Magnetic Flux - $\Phi$) ජාත්‍යන්තර සම්මත ඒකකය වෙබර් (Weber - $Wb$) වේ.<br>ටෙස්ලා (Tesla - $T$) යනු චුම්බක ස්‍රාව ඝනත්වයේ ($B$) ඒකකයයි. $\Phi = B \cdot A$ බැවින් $1\text{ Wb} = 1\text{ T m}^2$ ලෙසද දැක්විය හැක.', 'චුම්බක ස්‍රාවයේ (Magnetic Flux - $\Phi$) ජාත්‍යන්තර සම්මත ඒකකය වෙබර් (Weber - $Wb$) වේ.<br>ටෙස්ලා (Tesla - $T$) යනු චුම්බක ස්‍රාව ඝනත්වයේ ($B$) ඒකකයයි. $\Phi = B \cdot A$ බැවින් $1\text{ Wb} = 1\text{ T m}^2$ ලෙසද දැක්විය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
