INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f138926-4cca-450b-9978-0b4e046f97b4', 'ee6752a2-b496-56d9-9ebf-5d2b6bb95044', 'ප්‍රභාශ්වසනය සඳහා වැදගත් වීමයි.', 'ප්‍රභාශ්වසනය සඳහා වැදගත් වීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8d70a842-a79c-4bb9-beec-a39bd55011a3', 'ee6752a2-b496-56d9-9ebf-5d2b6bb95044', 'ගෙවී ගිය ඉන්ද්‍රියිකා ජීරණය කිරීමයි.', 'ගෙවී ගිය ඉන්ද්‍රියිකා ජීරණය කිරීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dc776659-8311-55f9-9ed8-bdefaab18a64', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 2, '<p>ජීවීන්ගේ පමණක් දැකිය හැකි ලක්ෂණ දෙකක් වන්නේ</p>', '<p>ජීවීන්ගේ පමණක් දැකිය හැකි ලක්ෂණ දෙකක් වන්නේ</p>', NULL, 'පරිවෘත්තිය (Metabolism) සහ ආවේණිය (Heredity) යන ලක්ෂණ සජීවීන්ට පමණක් සීමා වේ.<br>වර්ධනය, චලනය වැනි ලක්ෂණ අජීවී ද්‍රව්‍ය (උදාහරණ: ස්ඵටික වර්ධනය, ජලයේ චලනය) වල ද යම් මට්ටමකින් නිරීක්ෂණය කළ හැක.', 'පරිවෘත්තිය (Metabolism) සහ ආවේණිය (Heredity) යන ලක්ෂණ සජීවීන්ට පමණක් සීමා වේ.<br>වර්ධනය, චලනය වැනි ලක්ෂණ අජීවී ද්‍රව්‍ය (උදාහරණ: ස්ඵටික වර්ධනය, ජලයේ චලනය) වල ද යම් මට්ටමකින් නිරීක්ෂණය කළ හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
