INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9b85b0bf-adb8-474c-a4f4-7f723b99889f', 'a8a3bcf7-fde0-582e-8464-fcb2b75fb513', 'නිදර්ශකවල ත්‍රිමාන පෙනුම නිරීක්ෂණය කළ හැකි ය.', 'නිදර්ශකවල ත්‍රිමාන පෙනුම නිරීක්ෂණය කළ හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('596ddf9d-6902-45d1-8d01-e4605fb4aa03', 'a8a3bcf7-fde0-582e-8464-fcb2b75fb513', 'නිදර්ශක මගින් ඉලෙක්ට්‍රෝන වැඩි ප්‍රමාණයක් විසුරුවනු ලබන අතර ඉතිරි ඒවා අවශෝෂණය කෙරේ.', 'නිදර්ශක මගින් ඉලෙක්ට්‍රෝන වැඩි ප්‍රමාණයක් විසුරුවනු ලබන අතර ඉතිරි ඒවා අවශෝෂණය කෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f1dde450-3624-5463-9060-d9de14f38ab1', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 4, '<p>සුන්‍යෂ්ටික සෛල චක්‍රයේදී, සිදුවීම සහ කලාව නිවැරදිව දක්වන ප්‍රතිචාරය තෝරන්න.</p>', '<p>සුන්‍යෂ්ටික සෛල චක්‍රයේදී, සිදුවීම සහ කලාව නිවැරදිව දක්වන ප්‍රතිචාරය තෝරන්න.</p>', NULL, 'සුන්‍යෂ්ටික සෛල චක්‍රයේ $G_1$ කලාවේදී ප්‍රධාන වශයෙන් සෛල වර්ධනය සඳහා අවශ්‍ය ප්‍රෝටීන සංශ්ලේෂණය සහ සෛලීය ඉන්ද්‍රියිකා නිපදවීම සිදු වේ.<br>DNA ප්‍රතිවලිත වීම සිදු වන්නේ $S$ කලාවේදී ය. කේන්ද්‍ර දේහ ද්විකරණය වීම ද අන්තර්කලාවේදී (ප්‍රධාන වශයෙන් $S$ හෝ $G_2$) සිදුවේ.', 'සුන්‍යෂ්ටික සෛල චක්‍රයේ $G_1$ කලාවේදී ප්‍රධාන වශයෙන් සෛල වර්ධනය සඳහා අවශ්‍ය ප්‍රෝටීන සංශ්ලේෂණය සහ සෛලීය ඉන්ද්‍රියිකා නිපදවීම සිදු වේ.<br>DNA ප්‍රතිවලිත වීම සිදු වන්නේ $S$ කලාවේදී ය. කේන්ද්‍ර දේහ ද්විකරණය වීම ද අන්තර්කලාවේදී (ප්‍රධාන වශයෙන් $S$ හෝ $G_2$) සිදුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
