INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eb527e67-a4be-4a29-9ff6-f57c0c514609', 'f1dde450-3624-5463-9060-d9de14f38ab1', 'ක්‍රොමැටින් සෑදීම - $G_1$ කලාව', 'ක්‍රොමැටින් සෑදීම - $G_1$ කලාව', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0bf95878-948d-416a-95b4-fe6a60232415', 'f1dde450-3624-5463-9060-d9de14f38ab1', 'සෛලීය ඉන්ද්‍රියිකා නිපද වීම - $S$ කලාව', 'සෛලීය ඉන්ද්‍රියිකා නිපද වීම - $S$ කලාව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fff3d258-2b4c-40c6-971a-b7bcd2bb11b1', 'f1dde450-3624-5463-9060-d9de14f38ab1', 'කේන්ද්‍ර දේහය ද්විකරණය වීම - $M$ කලාව', 'කේන්ද්‍ර දේහය ද්විකරණය වීම - $M$ කලාව', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3070e971-1fac-5c8f-af9f-d7ee77ac4628', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 5, '<p>එන්සයිම වල ඇලොස්ටරික යාමනයේදී</p>', '<p>එන්සයිම වල ඇලොස්ටරික යාමනයේදී</p>', NULL, 'ඇලොස්ටරික යාමනයේදී යාමක අණු එන්සයිමයේ ඇලොස්ටරික ස්ථානයකට සහසංයුජ නොවන අන්තර්ක්‍රියා (non-covalent interactions) මගින් බැඳේ.<br>මෙමගින් එන්සයිමයේ හැඩය වෙනස් වී එහි සක්‍රියතාව යාමනය (සක්‍රිය වීම හෝ නිශේධනය වීම) සිදු වේ.', 'ඇලොස්ටරික යාමනයේදී යාමක අණු එන්සයිමයේ ඇලොස්ටරික ස්ථානයකට සහසංයුජ නොවන අන්තර්ක්‍රියා (non-covalent interactions) මගින් බැඳේ.<br>මෙමගින් එන්සයිමයේ හැඩය වෙනස් වී එහි සක්‍රියතාව යාමනය (සක්‍රිය වීම හෝ නිශේධනය වීම) සිදු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
