INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f82f3a7a-6fe7-4387-8683-89d57ccc3178', '3070e971-1fac-5c8f-af9f-d7ee77ac4628', 'කිසියම් උපඒකකයකට බැඳෙන සක්‍රියක අණුවක්, එම උපඒකකයේ සක්‍රිය ස්ථානයට පමණක් බලපායි.', 'කිසියම් උපඒකකයකට බැඳෙන සක්‍රියක අණුවක්, එම උපඒකකයේ සක්‍රිය ස්ථානයට පමණක් බලපායි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7916261a-554b-40c0-968e-e2a82d53b655', '3070e971-1fac-5c8f-af9f-d7ee77ac4628', 'නිශේධක අණු එන්සයිමයේ කෘත්‍යයට බලපාන නමුත් එහි හැඩයට බලපෑමක් ඇති නොකරයි.', 'නිශේධක අණු එන්සයිමයේ කෘත්‍යයට බලපාන නමුත් එහි හැඩයට බලපෑමක් ඇති නොකරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7dc69a85-0d2a-468f-a4dc-1c7261c7c307', '3070e971-1fac-5c8f-af9f-d7ee77ac4628', 'ATP ඇලොස්ටරික සක්‍රියකයක් ලෙස ක්‍රියා කරයි.', 'ATP ඇලොස්ටරික සක්‍රියකයක් ලෙස ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('37562036-a581-5efb-9586-963095563eb3', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 6, '<p>එතිල් මධ්‍යසාර පැසීමේදී</p>', '<p>එතිල් මධ්‍යසාර පැසීමේදී</p>', NULL, 'එතිල් මධ්‍යසාර පැසීමේදී ග්ලයිකොලිසිය මගින් එක් ග්ලූකෝස් අණුවකින් ශුද්ධ ATP අණු දෙකක් නිපදවේ.<br>මෙහිදී පයිරුවේට් පළමුව ඇසිටැල්ඩිහයිඩ් බවට පත් වී (එහිදී $CO_2$ අණු 2ක් පිටවේ), ඉන්පසු එය NADH මගින් ඔක්සිහරණය වී එතනෝල් නිපදවයි. අවසාන හයිඩ්‍රජන් ප්‍රතිග්‍රාහකයා වන්නේ කාබනික සංයෝගයක් වන ඇසිටැල්ඩිහයිඩ් ය.', 'එතිල් මධ්‍යසාර පැසීමේදී ග්ලයිකොලිසිය මගින් එක් ග්ලූකෝස් අණුවකින් ශුද්ධ ATP අණු දෙකක් නිපදවේ.<br>මෙහිදී පයිරුවේට් පළමුව ඇසිටැල්ඩිහයිඩ් බවට පත් වී (එහිදී $CO_2$ අණු 2ක් පිටවේ), ඉන්පසු එය NADH මගින් ඔක්සිහරණය වී එතනෝල් නිපදවයි. අවසාන හයිඩ්‍රජන් ප්‍රතිග්‍රාහකයා වන්නේ කාබනික සංයෝගයක් වන ඇසිටැල්ඩිහයිඩ් ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30d2e3c1-e8d0-43bc-8d1b-d3ebe0afabd2', '37562036-a581-5efb-9586-963095563eb3', 'එක් ග්ලූකෝස් අණුවකින් පයිරුවේට් අණුවක් සහ NADH අණු දෙකක් නිපද වේ.', 'එක් ග්ලූකෝස් අණුවකින් පයිරුවේට් අණුවක් සහ NADH අණු දෙකක් නිපද වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8edd86f3-f2d2-420a-8baf-d75cb6865630', '37562036-a581-5efb-9586-963095563eb3', 'NADH භාවිත කර පයිරුවේට් කෙළින්ම එතනොල් බවට ඔක්සිහරණය කෙරේ.', 'NADH භාවිත කර පයිරුවේට් කෙළින්ම එතනොල් බවට ඔක්සිහරණය කෙරේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('11129271-ec65-477a-8698-6f6c55b5faf2', '37562036-a581-5efb-9586-963095563eb3', 'එක් ග්ලූකෝස් අණුවකින් එක් $CO_2$ අණුවක් නිපද වේ.', 'එක් ග්ලූකෝස් අණුවකින් එක් $CO_2$ අණුවක් නිපද වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('461161fb-2b39-4fb2-9062-91d4be1a92b0', '37562036-a581-5efb-9586-963095563eb3', 'අවසාන හයිඩ්‍රජන් ප්‍රතිග්‍රාහකයා වන්නේ අකාබනික සංයෝගයකි.', 'අවසාන හයිඩ්‍රජන් ප්‍රතිග්‍රාහකයා වන්නේ අකාබනික සංයෝගයකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ee52deca-aa1e-46ef-96c3-7fc7763d51a2', '37562036-a581-5efb-9586-963095563eb3', 'එක් ග්ලූකෝස් අණුවකින් ATP අණු දෙකක් නිපද වේ.', 'එක් ග්ලූකෝස් අණුවකින් ATP අණු දෙකක් නිපද වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('52f057ab-4583-5a0c-bc9e-8b244349aaeb', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 7, '<p>ග්ලූකෝස් අණුවක ග්ලයිකොලිසිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ග්ලූකෝස් අණුවක ග්ලයිකොලිසිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ග්ලයිකොලිසියේදී එක් ග්ලූකෝස් අණුවක් බිඳවැටීමෙන් පයිරුවේට් අණු 2ක්, ශුද්ධ ATP අණු 2ක් සහ NADH අණු 2ක් නිපදවේ.<br>මෙම ක්‍රියාවලිය සම්පූර්ණයෙන්ම සෛල ප්ලාස්මය තුළ සිදුවන අතර එයට ඔක්සිජන් අවශ්‍ය නොවේ.', 'ග්ලයිකොලිසියේදී එක් ග්ලූකෝස් අණුවක් බිඳවැටීමෙන් පයිරුවේට් අණු 2ක්, ශුද්ධ ATP අණු 2ක් සහ NADH අණු 2ක් නිපදවේ.<br>මෙම ක්‍රියාවලිය සම්පූර්ණයෙන්ම සෛල ප්ලාස්මය තුළ සිදුවන අතර එයට ඔක්සිජන් අවශ්‍ය නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
