INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5cb00e64-51a0-4add-bb29-f8d2b97bf4d6', '52f057ab-4583-5a0c-bc9e-8b244349aaeb', 'එය අණුක ඔක්සිජන් මත අර්ධ ලෙස රඳා පවතී.', 'එය අණුක ඔක්සිජන් මත අර්ධ ලෙස රඳා පවතී.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b71fbcc1-fd13-4d80-9de2-de22219a5c9e', '52f057ab-4583-5a0c-bc9e-8b244349aaeb', 'NADH අණු දෙකක් නිපද වේ.', 'NADH අණු දෙකක් නිපද වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d901a01-a395-4dde-a232-d430d5e61ddd', '52f057ab-4583-5a0c-bc9e-8b244349aaeb', 'ග්ලයිකොලිසියෙන් කොටසක් මයිටොකොන්ඩ්‍රියමේ පිටත පටලයේ සිදු වේ.', 'ග්ලයිකොලිසියෙන් කොටසක් මයිටොකොන්ඩ්‍රියමේ පිටත පටලයේ සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('87220e4b-ed2e-56ce-9ebb-8053c2d8e9ca', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 8, '<p>ජීවීන් පරිණාමය වීමේදී ඇති වූ සිද්ධීන් කීපයක් පහත දැක්වේ.<br><br>A - ජල පද්ධති ඔක්සිජන් මගින් සන්තෘප්ත වීම<br>B - $Fe^{2+}$ ඔක්සිකරණය වීම<br>C - ප්‍රභාසංශ්ලේෂක බැක්ටීරියා ගහන වැඩි වීම<br>D - සයනොබැක්ටීරියා සම්භවය වීම<br><br>ඉහත සිද්ධීන්වල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', '<p>ජීවීන් පරිණාමය වීමේදී ඇති වූ සිද්ධීන් කීපයක් පහත දැක්වේ.<br><br>A - ජල පද්ධති ඔක්සිජන් මගින් සන්තෘප්ත වීම<br>B - $Fe^{2+}$ ඔක්සිකරණය වීම<br>C - ප්‍රභාසංශ්ලේෂක බැක්ටීරියා ගහන වැඩි වීම<br>D - සයනොබැක්ටීරියා සම්භවය වීම<br><br>ඉහත සිද්ධීන්වල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', NULL, 'සයනොබැක්ටීරියා සම්භවය වීමෙන් (D) පසුව ඒවායේ ගහනය වැඩි වී ප්‍රභාසංශ්ලේෂණය හේතුවෙන් ඔක්සිජන් නිපදවීම ඉහළ යයි (C). එම ඔක්සිජන් සාගර ජලයේ ඇති $Fe^{2+}$ සමඟ ප්‍රතික්‍රියා කර ඔක්සිකරණය වේ (B). ඉන්පසුව ජල පද්ධති ඔක්සිජන් මගින් සන්තෘප්ත වේ (A). එබැවින් නිවැරදි අනුපිළිවෙළ D, C, B, A වේ.', 'සයනොබැක්ටීරියා සම්භවය වීමෙන් (D) පසුව ඒවායේ ගහනය වැඩි වී ප්‍රභාසංශ්ලේෂණය හේතුවෙන් ඔක්සිජන් නිපදවීම ඉහළ යයි (C). එම ඔක්සිජන් සාගර ජලයේ ඇති $Fe^{2+}$ සමඟ ප්‍රතික්‍රියා කර ඔක්සිකරණය වේ (B). ඉන්පසුව ජල පද්ධති ඔක්සිජන් මගින් සන්තෘප්ත වේ (A). එබැවින් නිවැරදි අනුපිළිවෙළ D, C, B, A වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
