INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e5ec6f3e-7e4e-4a19-ae60-3db799138376', '6db72d23-f6ed-5e85-8817-6b297e4b321a', 'ශෛලම වාහිනී ඒකක දිගැටි, දෙකෙළවර උල් වූ සෛල වේ.', 'ශෛලම වාහිනී ඒකක දිගැටි, දෙකෙළවර උල් වූ සෛල වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2aca193f-2cbb-4e65-8a11-1248d48a7886', '6db72d23-f6ed-5e85-8817-6b297e4b321a', 'වාහකාභ බ්‍රයෝෆයිටාවල කඳන් වලට සංධාරණය සපයයි.', 'වාහකාභ බ්‍රයෝෆයිටාවල කඳන් වලට සංධාරණය සපයයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('04d9f331-6424-4ee2-970f-29bafe3baaf6', '6db72d23-f6ed-5e85-8817-6b297e4b321a', 'සහචර සෛල සයිකඩොෆයිටාවල ඇත.', 'සහචර සෛල සයිකඩොෆයිටාවල ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7b228e5-e22b-4aa1-98fa-b633ef3921ed', '6db72d23-f6ed-5e85-8817-6b297e4b321a', 'පෙනේර නල ඒකක අතර කූප ඇත.', 'පෙනේර නල ඒකක අතර කූප ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('22a18e4a-8713-5fee-983d-5947a128c865', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 12, '<p>ශාක ව්‍යුහ කීපයක් සහ ඒවායේ කෘත්‍ය පහත දැක් වේ.<br><br>ව්‍යුහය<br>A - වා සිදුරු<br>B - පූටිකා<br>C - ජල සිදුරු<br><br>කෘත්‍යය<br>P - උත්ස්වේදනය<br>Q - වායු හුවමාරුව<br>R - බින්දුදය<br><br>සියලුම ''ව්‍යුහය - කෘත්‍යය'' සංකලන නිවැරදි වන ප්‍රතිචාරය තෝරන්න.</p>', '<p>ශාක ව්‍යුහ කීපයක් සහ ඒවායේ කෘත්‍ය පහත දැක් වේ.<br><br>ව්‍යුහය<br>A - වා සිදුරු<br>B - පූටිකා<br>C - ජල සිදුරු<br><br>කෘත්‍යය<br>P - උත්ස්වේදනය<br>Q - වායු හුවමාරුව<br>R - බින්දුදය<br><br>සියලුම ''ව්‍යුහය - කෘත්‍යය'' සංකලන නිවැරදි වන ප්‍රතිචාරය තෝරන්න.</p>', NULL, 'වා සිදුරු (Lenticels) මගින් සුළු වශයෙන් උත්ස්වේදනය (ලෙන්ටිකියුලර් උත්ස්වේදනය - P) සිදු වේ. පූටිකා (Stomata) හරහා ප්‍රධාන වශයෙන් වායු හුවමාරුව (Q) මෙන්ම උත්ස්වේදනය ද සිදු වේ. ජල සිදුරු (Hydathodes) හරහා බින්දුදය (Guttation - R) සිදු වේ.<br>එබැවින් වඩාත් ජෛව විද්‍යාත්මකව ගැළපෙන පිළිතුර වන්නේ A-P, B-Q, C-R ය.', 'වා සිදුරු (Lenticels) මගින් සුළු වශයෙන් උත්ස්වේදනය (ලෙන්ටිකියුලර් උත්ස්වේදනය - P) සිදු වේ. පූටිකා (Stomata) හරහා ප්‍රධාන වශයෙන් වායු හුවමාරුව (Q) මෙන්ම උත්ස්වේදනය ද සිදු වේ. ජල සිදුරු (Hydathodes) හරහා බින්දුදය (Guttation - R) සිදු වේ.<br>එබැවින් වඩාත් ජෛව විද්‍යාත්මකව ගැළපෙන පිළිතුර වන්නේ A-P, B-Q, C-R ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
