INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 17, '<p>අපිච්ඡදය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>අපිච්ඡදය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'සරල ඝනාකාර අපිච්ඡදය (Simple cuboidal epithelium) ප්‍රධාන වශයෙන් ශ්‍රාවය කිරීම් සහ අවශෝෂණය කිරීම් සිදු කරන අතර, එය ඛේට ග්‍රන්ථිවල සහ වෘක්ක නාලිකාවල දක්නට ලැබේ.<br>ස්තරීභූත ශල්කමය අපිච්ඡදය ප්‍රධාන වශයෙන් ආරක්ෂාව සපයයි. ව්‍යාජ ස්තරීභූත අපිච්ඡදය සරල අපිච්ඡද වර්ගයකි. සරල ස්තම්භික අපිච්ඡදය අන්ත්‍රයේ ඇති නමුත් නාස් මාර්ගයේ ඇත්තේ ව්‍යාජ ස්තරීභූත අපිච්ඡදයකි. සරල ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුවට (විසරණයට) පහසුකම් සලසයි.', 'සරල ඝනාකාර අපිච්ඡදය (Simple cuboidal epithelium) ප්‍රධාන වශයෙන් ශ්‍රාවය කිරීම් සහ අවශෝෂණය කිරීම් සිදු කරන අතර, එය ඛේට ග්‍රන්ථිවල සහ වෘක්ක නාලිකාවල දක්නට ලැබේ.<br>ස්තරීභූත ශල්කමය අපිච්ඡදය ප්‍රධාන වශයෙන් ආරක්ෂාව සපයයි. ව්‍යාජ ස්තරීභූත අපිච්ඡදය සරල අපිච්ඡද වර්ගයකි. සරල ස්තම්භික අපිච්ඡදය අන්ත්‍රයේ ඇති නමුත් නාස් මාර්ගයේ ඇත්තේ ව්‍යාජ ස්තරීභූත අපිච්ඡදයකි. සරල ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුවට (විසරණයට) පහසුකම් සලසයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e51621d6-592e-415f-beb7-0e38fa2c8024', 'bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'ස්තරීභූත ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුව සඳහා දායක වේ.', 'ස්තරීභූත ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුව සඳහා දායක වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f610d777-7091-4a22-b5ae-8b70c833e86f', 'bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'ව්‍යාජ ස්තරීභූත ස්තම්භික අපිච්ඡදය සංයුක්ත අපිච්ඡද පටකයකි.', 'ව්‍යාජ ස්තරීභූත ස්තම්භික අපිච්ඡදය සංයුක්ත අපිච්ඡද පටකයකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9c9f8185-474d-4b40-9122-09644710d88a', 'bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'සරල ස්තම්භික අපිච්ඡදය අන්ත්‍රයේ සහ නාස් මාර්ගයේ පිහිටයි.', 'සරල ස්තම්භික අපිච්ඡදය අන්ත්‍රයේ සහ නාස් මාර්ගයේ පිහිටයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c100758a-3562-4293-879e-c81492aa5b8d', 'bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'සරල ඝනාකාර අපිච්ඡදය ඛේට ග්‍රන්ථි සහ වෘක්ක නාලිකා වල ඇත.', 'සරල ඝනාකාර අපිච්ඡදය ඛේට ග්‍රන්ථි සහ වෘක්ක නාලිකා වල ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2c701f3c-9699-478c-bfd3-bd68b2ce0c37', 'bf32a0f5-7aab-569d-b588-2b7c9a463af1', 'සරල ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුව වළකයි.', 'සරල ශල්කමය අපිච්ඡදය ද්‍රව්‍ය හුවමාරුව වළකයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('60abe504-467d-5442-a9a8-d6100899cd6a', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 18, '<p>ජීවීන් අතර දක්නට ලැබෙන සහජීවන ආකාර තුන නිදසුන් සහිතව පහත දැක් වේ.<br><br>A: අන්‍යෝන්‍යාධාරය - ගවයා සහ කොකා<br>B: පරපෝෂිතාව - මිනිසා සහ Planaria<br>C: සහභෝජිත්වය - තල්මසා සහ බෙලි ඇණයා<br><br>ඉහත සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද? කුමන ඒවාද?</p>', '<p>ජීවීන් අතර දක්නට ලැබෙන සහජීවන ආකාර තුන නිදසුන් සහිතව පහත දැක් වේ.<br><br>A: අන්‍යෝන්‍යාධාරය - ගවයා සහ කොකා<br>B: පරපෝෂිතාව - මිනිසා සහ Planaria<br>C: සහභෝජිත්වය - තල්මසා සහ බෙලි ඇණයා<br><br>ඉහත සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද? කුමන ඒවාද?</p>', NULL, 'සහභෝජිත්වය (Commensalism) යනු එක් ජීවියෙකුට වාසි සැලසෙන අතර අනෙකාට වාසියක් හෝ හානියක් නොවන සම්බන්ධතාවකි. තල්මසා සහ බෙලි ඇණයා (Barnacle) මීට නිදසුනකි.<br>ගවයා සහ කොකා (Cattle and egret) අතර ඇත්තේ ද සහභෝජිත්වයකි, අන්‍යෝන්‍යාධාරය නොවේ. ප්ලැනේරියා (Planaria) නිදහස්ව ජීවත් වන සත්ත්වයෙකු මිස පරපෝෂිතයෙකු නොවේ.', 'සහභෝජිත්වය (Commensalism) යනු එක් ජීවියෙකුට වාසි සැලසෙන අතර අනෙකාට වාසියක් හෝ හානියක් නොවන සම්බන්ධතාවකි. තල්මසා සහ බෙලි ඇණයා (Barnacle) මීට නිදසුනකි.<br>ගවයා සහ කොකා (Cattle and egret) අතර ඇත්තේ ද සහභෝජිත්වයකි, අන්‍යෝන්‍යාධාරය නොවේ. ප්ලැනේරියා (Planaria) නිදහස්ව ජීවත් වන සත්ත්වයෙකු මිස පරපෝෂිතයෙකු නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
