INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('722fa48b-74f7-4eb9-bdbe-b11af49e5cb2', '26d53db7-58fa-5b18-81dc-04214dd0c611', 'දකුණු කර්ණිකාව, ද්විතුණ්ඩ කපාටය, දකුණු කෝෂිකාව, පුප්ඵුශීය කපාටය, වම් කර්ණිකාව, ත්‍රිතුණ්ඩ කපාටය, වම් කෝෂිකාව', 'දකුණු කර්ණිකාව, ද්විතුණ්ඩ කපාටය, දකුණු කෝෂිකාව, පුප්ඵුශීය කපාටය, වම් කර්ණිකාව, ත්‍රිතුණ්ඩ කපාටය, වම් කෝෂිකාව', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('637b2f1d-dda6-5ad4-85aa-075d2dfd5412', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 21, '<p>මානව රුධිරය තුළ කාබන්ඩයොක්සයිඩ් අඩුම සහ වැඩිම ප්‍රතිශත වලින් පරිවහනය වන ආකාර දක්වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>මානව රුධිරය තුළ කාබන්ඩයොක්සයිඩ් අඩුම සහ වැඩිම ප්‍රතිශත වලින් පරිවහනය වන ආකාර දක්වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'රුධිරය මගින් කාබන්ඩයොක්සයිඩ් ($CO_2$) පරිවහනය වන ප්‍රධාන ආකාර තුනකි:<br>1. ප්ලාස්මාවේ දිය වූ $CO_2$ ලෙස (අඩුම ප්‍රතිශතය - 7% පමණ)<br>2. කාබෑමයිනෝහීමොග්ලොබින් ලෙස රතු රුධිර සෛලවල හීමොග්ලොබින් සමඟ බැඳී (23% පමණ)<br>3. බයිකාබනේට් අයන ($HCO_3^-$) ලෙස (වැඩිම ප්‍රතිශතය - 70% පමණ).<br>එබැවින් අඩුම සහ වැඩිම ප්‍රතිශත පිළිවෙළින් දිය වූ $CO_2$ සහ $HCO_3^-$ වේ.', 'රුධිරය මගින් කාබන්ඩයොක්සයිඩ් ($CO_2$) පරිවහනය වන ප්‍රධාන ආකාර තුනකි:<br>1. ප්ලාස්මාවේ දිය වූ $CO_2$ ලෙස (අඩුම ප්‍රතිශතය - 7% පමණ)<br>2. කාබෑමයිනෝහීමොග්ලොබින් ලෙස රතු රුධිර සෛලවල හීමොග්ලොබින් සමඟ බැඳී (23% පමණ)<br>3. බයිකාබනේට් අයන ($HCO_3^-$) ලෙස (වැඩිම ප්‍රතිශතය - 70% පමණ).<br>එබැවින් අඩුම සහ වැඩිම ප්‍රතිශත පිළිවෙළින් දිය වූ $CO_2$ සහ $HCO_3^-$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f4ec4d81-4f11-45a7-89e8-88e63f8e0807', '637b2f1d-dda6-5ad4-85aa-075d2dfd5412', 'දිය වූ $CO_2$, කාබෑමයිනෝහීමොග්ලොබින්', 'දිය වූ $CO_2$, කාබෑමයිනෝහීමොග්ලොබින්', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eb97d7a4-07b1-4103-8749-826d67e37886', '637b2f1d-dda6-5ad4-85aa-075d2dfd5412', '$HCO_3^-$, කාබෑමයිනෝහීමොග්ලොබින්', '$HCO_3^-$, කාබෑමයිනෝහීමොග්ලොබින්', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eb47acf8-a97b-4f4a-ab2e-65b6a8afd6b8', '637b2f1d-dda6-5ad4-85aa-075d2dfd5412', 'කාබෑමයිනෝහීමොග්ලොබින්, දිය වූ $CO_2$', 'කාබෑමයිනෝහීමොග්ලොබින්, දිය වූ $CO_2$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('db4d0efe-67ef-43ce-a842-e8325c03bf97', '637b2f1d-dda6-5ad4-85aa-075d2dfd5412', '$HCO_3^-$, දිය වූ $CO_2$', '$HCO_3^-$, දිය වූ $CO_2$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29b9d4ed-0960-4c5d-af35-4265eb532575', '637b2f1d-dda6-5ad4-85aa-075d2dfd5412', 'දිය වූ $CO_2$, $HCO_3^-$', 'දිය වූ $CO_2$, $HCO_3^-$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f2ef3629-f177-57e6-bdfb-d330b182ef98', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 22, '<p>කිසියම් පුද්ගලයෙකුගේ උදම් පරිමාව, ශේෂ පරිමාව, ආශ්වාසක අතිරේක පරිමාව සහ ප්‍රශ්වාසක අතිරේක පරිමාව පිළිවෙළින් 500 mL, 1200 mL, 3100 mL සහ 1100 mL වේ නම් එම පුද්ගලයාගේ ජෛව ධාරිතාව</p>', '<p>කිසියම් පුද්ගලයෙකුගේ උදම් පරිමාව, ශේෂ පරිමාව, ආශ්වාසක අතිරේක පරිමාව සහ ප්‍රශ්වාසක අතිරේක පරිමාව පිළිවෙළින් 500 mL, 1200 mL, 3100 mL සහ 1100 mL වේ නම් එම පුද්ගලයාගේ ජෛව ධාරිතාව</p>', NULL, 'ජෛව ධාරිතාව (Vital Capacity - VC) යනු පුද්ගලයෙකුට උපරිම ආශ්වාසයකින් පසු පිට කළ හැකි උපරිම වාත පරිමාවයි. එයට උදම් පරිමාව (TV), ආශ්වාසක අතිරේක පරිමාව (IRV) සහ ප්‍රශ්වාසක අතිරේක පරිමාව (ERV) අයත් වේ.<br><br>ජෛව ධාරිතාව = $TV + IRV + ERV$<br>$VC = 500 + 3100 + 1100 = 4700 \text{ mL}$<br><br>මෙහිදී ශේෂ පරිමාව (1200 mL) ජෛව ධාරිතාවට අයත් නොවේ.', 'ජෛව ධාරිතාව (Vital Capacity - VC) යනු පුද්ගලයෙකුට උපරිම ආශ්වාසයකින් පසු පිට කළ හැකි උපරිම වාත පරිමාවයි. එයට උදම් පරිමාව (TV), ආශ්වාසක අතිරේක පරිමාව (IRV) සහ ප්‍රශ්වාසක අතිරේක පරිමාව (ERV) අයත් වේ.<br><br>ජෛව ධාරිතාව = $TV + IRV + ERV$<br>$VC = 500 + 3100 + 1100 = 4700 \text{ mL}$<br><br>මෙහිදී ශේෂ පරිමාව (1200 mL) ජෛව ධාරිතාවට අයත් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
