INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 23, '<p>මිනිසාගේ ස්වයංසාධක ස්නායු පද්ධතියේ ප්‍රත්‍යානුවේගී කොටස</p>', '<p>මිනිසාගේ ස්වයංසාධක ස්නායු පද්ධතියේ ප්‍රත්‍යානුවේගී කොටස</p>', NULL, 'ස්වයංසාධක ස්නායු පද්ධතියේ ප්‍රත්‍යානුවේගී (Parasympathetic) කොටස මගින් ''විවේකය සහ ජීරණය'' (rest and digest) ආශ්‍රිත ක්‍රියාවලි උත්තේජනය කරයි. මේ අනුව එය පිත්තාශය උත්තේජනය කර පිත ශ්‍රාවය කිරීම දිරිමත් කරයි.<br>අනෙකුත් විකල්ප සලකා බැලූ විට: ඛේට ශ්‍රාවය නිශේධනය කිරීම, කණිනිකාව විස්තාරණය, ශ්වාසනාලිකා ඉහිල් කිරීම (විස්තාරණය) සහ අක්මාවෙන් ග්ලූකෝස් නිදහස් කිරීම යන සියල්ලම සංවේගී (Sympathetic) ස්නායු පද්ධතියේ ක්‍රියාවන් ය.', 'ස්වයංසාධක ස්නායු පද්ධතියේ ප්‍රත්‍යානුවේගී (Parasympathetic) කොටස මගින් ''විවේකය සහ ජීරණය'' (rest and digest) ආශ්‍රිත ක්‍රියාවලි උත්තේජනය කරයි. මේ අනුව එය පිත්තාශය උත්තේජනය කර පිත ශ්‍රාවය කිරීම දිරිමත් කරයි.<br>අනෙකුත් විකල්ප සලකා බැලූ විට: ඛේට ශ්‍රාවය නිශේධනය කිරීම, කණිනිකාව විස්තාරණය, ශ්වාසනාලිකා ඉහිල් කිරීම (විස්තාරණය) සහ අක්මාවෙන් ග්ලූකෝස් නිදහස් කිරීම යන සියල්ලම සංවේගී (Sympathetic) ස්නායු පද්ධතියේ ක්‍රියාවන් ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d26f2d6c-4ad3-446c-91dd-3d8d2efc63f8', 'fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'ඛේටය ස්‍රාවය වීම නිශේධනය කරයි.', 'ඛේටය ස්‍රාවය වීම නිශේධනය කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8a88171-ca1f-49e0-94c9-38dd2ccd85f5', 'fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'ඇසේ කණිනිකාව විස්තාරණය කරයි.', 'ඇසේ කණිනිකාව විස්තාරණය කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('06aa4e62-9d4e-4f7c-a070-2113db1ee539', 'fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'පෙනහැලි තුළ ඇති ශ්වාසනාලිකා ඉහිල් කරයි.', 'පෙනහැලි තුළ ඇති ශ්වාසනාලිකා ඉහිල් කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2e83b00e-f2ed-4708-b6bd-deacc2c7c302', 'fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'අක්මාවෙන් ග්ලූකෝස් නිදහස් කිරීම උත්තේජනය කරයි.', 'අක්මාවෙන් ග්ලූකෝස් නිදහස් කිරීම උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('87babda1-1529-44b3-a363-e085e2e69aaa', 'fb32ea2d-67d5-506a-8e83-7ec0a4a7b803', 'පිත්තාශය උත්තේජනය කරයි.', 'පිත්තාශය උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 24, '<p>මානව දෘෂ්ටිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මානව දෘෂ්ටිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'සමීප වස්තූන් දෙස බැලීමේදී ඒවායේ සිට එන ආලෝක කිරණ වඩාත් අපසාරී වන බැවින්, ඒවා දෘෂ්ටි විතානය මත නාභිගත කිරීම සඳහා අක්ෂි කාචයේ වක්‍රතාව (වර්තන බලය) වැඩි කළ යුතුය. මෙම ක්‍රියාවලිය අක්ෂි ප්‍රතියෝජනය (Accommodation) ලෙස හැඳින්වෙන අතර එය සමීප පෙනීම සඳහා අත්‍යවශ්‍ය වේ.<br>අක්ෂි ප්‍රතියෝජනය සිදුකරන්නේ කාචය මගිනි, ස්වච්ඡය මගින් නොවේ. යෂ්ටි සෛලවල ඇත්තේ රොඩොප්සින් ය (ෆොටොප්සින් ඇත්තේ කේතු සෛලවල ය). දෘෂ්ටි සංජානනය සිදු වන්නේ අපර කපාල ඛණ්ඩිකාවේ (Occipital lobe) ය.', 'සමීප වස්තූන් දෙස බැලීමේදී ඒවායේ සිට එන ආලෝක කිරණ වඩාත් අපසාරී වන බැවින්, ඒවා දෘෂ්ටි විතානය මත නාභිගත කිරීම සඳහා අක්ෂි කාචයේ වක්‍රතාව (වර්තන බලය) වැඩි කළ යුතුය. මෙම ක්‍රියාවලිය අක්ෂි ප්‍රතියෝජනය (Accommodation) ලෙස හැඳින්වෙන අතර එය සමීප පෙනීම සඳහා අත්‍යවශ්‍ය වේ.<br>අක්ෂි ප්‍රතියෝජනය සිදුකරන්නේ කාචය මගිනි, ස්වච්ඡය මගින් නොවේ. යෂ්ටි සෛලවල ඇත්තේ රොඩොප්සින් ය (ෆොටොප්සින් ඇත්තේ කේතු සෛලවල ය). දෘෂ්ටි සංජානනය සිදු වන්නේ අපර කපාල ඛණ්ඩිකාවේ (Occipital lobe) ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('863b7368-f4cb-4d12-9279-722fd3fdbfe5', '195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'ස්වච්ඡයේ වර්තන බලය වෙනස් කිරීම මගින් ද්විනෙත්‍රික දෘෂ්ටිය පහසු කෙරේ.', 'ස්වච්ඡයේ වර්තන බලය වෙනස් කිරීම මගින් ද්විනෙත්‍රික දෘෂ්ටිය පහසු කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec3d130b-d788-4f05-9362-c69cd5ee61f8', '195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'දුර පෙනීමේදී අභිසාරිතාව සිදු වේ.', 'දුර පෙනීමේදී අභිසාරිතාව සිදු වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bf6f4992-b1f7-4ad3-8b8d-4688572cf01f', '195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'සමීප පෙනීම සඳහා අක්ෂි ප්‍රතියෝජනය වැදගත් වේ.', 'සමීප පෙනීම සඳහා අක්ෂි ප්‍රතියෝජනය වැදගත් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d695ecdb-54a1-4f6f-9990-115e465ea937', '195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'යෂ්ටි වල ඇති ෆොටොප්සින් රාත්‍රී පෙනීම ලබා දේ.', 'යෂ්ටි වල ඇති ෆොටොප්සින් රාත්‍රී පෙනීම ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e83020e-e8a9-4f80-a46d-0d1108d16434', '195fdf5d-8dc4-51a6-bb58-56c563ca8556', 'පෙනෙන වස්තුවල නිවැරදි සංජානනය සිදු වන්නේ මස්තිෂ්කයේ ලලාට ඛණ්ඩිකාවේදී ය.', 'පෙනෙන වස්තුවල නිවැරදි සංජානනය සිදු වන්නේ මස්තිෂ්කයේ ලලාට ඛණ්ඩිකාවේදී ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('25e0a20d-b313-570b-bf22-504da39bdde2', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 25, '<p>හෝමෝනය සහ එහි කෘත්‍යය නිවැරදිව ගැළපෙන්නේ පහත සඳහන් කුමන සංකලනයේද?</p>', '<p>හෝමෝනය සහ එහි කෘත්‍යය නිවැරදිව ගැළපෙන්නේ පහත සඳහන් කුමන සංකලනයේද?</p>', NULL, 'කොලිසිස්ටොකයිනින් (CCK) හෝමෝනය අන්ත්‍රය මගින් ශ්‍රාවය වන අතර, එය අග්න්‍යාශය උත්තේජනය කර ඇමයිලේස් වැනි ජීරක එන්සයිම නිදහස් කිරීම සිදු කරයි.<br>අනෙකුත් ඒවා වැරදි වන්නේ: ACTH මගින් උත්තේජනය කරන්නේ අධිවෘක්ක බාහිකයේ හෝමෝන (කෝටිසෝල් ආදිය) ශ්‍රාවයයි. කිරි නිපදවීම උත්තේජනය කරන්නේ ප්‍රොලැක්ටින් ය (ඔක්සිටොසින් මගින් කිරි පිටවීම සිදු කරයි). කැල්සිටොනින් මගින් රුධිර කැල්සියම් මට්ටම අඩු කරයි. මෙලටොනින් නින්ද-අවදි චක්‍රය යාමනය කරන අතර මූලික පරිවෘත්තීය වේගය පාලනය කරන්නේ තයිරොක්සින් ය.', 'කොලිසිස්ටොකයිනින් (CCK) හෝමෝනය අන්ත්‍රය මගින් ශ්‍රාවය වන අතර, එය අග්න්‍යාශය උත්තේජනය කර ඇමයිලේස් වැනි ජීරක එන්සයිම නිදහස් කිරීම සිදු කරයි.<br>අනෙකුත් ඒවා වැරදි වන්නේ: ACTH මගින් උත්තේජනය කරන්නේ අධිවෘක්ක බාහිකයේ හෝමෝන (කෝටිසෝල් ආදිය) ශ්‍රාවයයි. කිරි නිපදවීම උත්තේජනය කරන්නේ ප්‍රොලැක්ටින් ය (ඔක්සිටොසින් මගින් කිරි පිටවීම සිදු කරයි). කැල්සිටොනින් මගින් රුධිර කැල්සියම් මට්ටම අඩු කරයි. මෙලටොනින් නින්ද-අවදි චක්‍රය යාමනය කරන අතර මූලික පරිවෘත්තීය වේගය පාලනය කරන්නේ තයිරොක්සින් ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
