INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7dc9e1bd-771b-4586-b9a3-4b503217b322', 'f27a6759-4a33-5d99-a771-53423d50f3b5', 'කලලබන්ධයේ ඇත්තේ භ්‍රෑණ රුධිර වාහිනී පමණි.', 'කලලබන්ධයේ ඇත්තේ භ්‍රෑණ රුධිර වාහිනී පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f48faaed-abaa-460d-8190-ff44c633d27d', 'f27a6759-4a33-5d99-a771-53423d50f3b5', 'ගර්භණී භාවයේ 8 - 10 සතිවලදී භ්‍රෑණයේ හෘදය ස්පන්දනය වීම ආරම්භ වේ.', 'ගර්භණී භාවයේ 8 - 10 සතිවලදී භ්‍රෑණයේ හෘදය ස්පන්දනය වීම ආරම්භ වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e51052f-d8f3-563e-bfe4-dace14c41475', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 28, '<p>මිනිසාගේ ආක්ෂක සැකිල්ල පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මිනිසාගේ ආක්ෂක සැකිල්ල පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'මානව පර්ශු යුගල් 12 න්, පළමු යුගල් 7 ''සත්‍ය පර්ශු'' (True ribs) වන අතර ඒවා ඍජුවම උරස්තලයට (Sternum) සම්බන්ධ වේ. 8, 9, 10 යන පර්ශු යුගල් 3 ''අසත්‍ය පර්ශු'' (False ribs) වන අතර ඒවා උරස්තලය සමඟ සම්බන්ධ වන්නේ 7 වන පර්ශුවේ කාටිලේජය හරහා අනියම් (indirect) ලෙසිනි. 11 සහ 12 පාවෙන පර්ශු වේ.<br>ත්‍රිකාස්ථිය තැනෙන්නේ කශේරුකා 5ක් හා වීමෙනි. හිස සෘජුව තබාගැනීමට වැදගත් වන්නේ ග්‍රීව වක්‍රය විකසනය වීමයි.', 'මානව පර්ශු යුගල් 12 න්, පළමු යුගල් 7 ''සත්‍ය පර්ශු'' (True ribs) වන අතර ඒවා ඍජුවම උරස්තලයට (Sternum) සම්බන්ධ වේ. 8, 9, 10 යන පර්ශු යුගල් 3 ''අසත්‍ය පර්ශු'' (False ribs) වන අතර ඒවා උරස්තලය සමඟ සම්බන්ධ වන්නේ 7 වන පර්ශුවේ කාටිලේජය හරහා අනියම් (indirect) ලෙසිනි. 11 සහ 12 පාවෙන පර්ශු වේ.<br>ත්‍රිකාස්ථිය තැනෙන්නේ කශේරුකා 5ක් හා වීමෙනි. හිස සෘජුව තබාගැනීමට වැදගත් වන්නේ ග්‍රීව වක්‍රය විකසනය වීමයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0a71dc69-a20a-47d3-8ba7-bf14a04b7781', '5e51052f-d8f3-563e-bfe4-dace14c41475', 'පර්ශු යුගල් තුනක් උරස්තලය සමඟ අනියම් ලෙස සම්බන්ධ වේ.', 'පර්ශු යුගල් තුනක් උරස්තලය සමඟ අනියම් ලෙස සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8850f364-0196-4ef5-a865-8558d9cf1e5f', '5e51052f-d8f3-563e-bfe4-dace14c41475', 'යුග චක්‍රය, උඩු හනුව චලනය කිරීම සඳහා අවශ්‍ය පේශී සවි වීමට පෘෂ්ඨය සපයයි.', 'යුග චක්‍රය, උඩු හනුව චලනය කිරීම සඳහා අවශ්‍ය පේශී සවි වීමට පෘෂ්ඨය සපයයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aa613144-e7ab-45e7-a5bb-f47d1cafb106', '5e51052f-d8f3-563e-bfe4-dace14c41475', 'ත්‍රිකාස්ථිය තැනී ඇත්තේ අවශිෂ්ට කශේරුකා හතක් එකට හා වීමෙනි.', 'ත්‍රිකාස්ථිය තැනී ඇත්තේ අවශිෂ්ට කශේරුකා හතක් එකට හා වීමෙනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d20efdac-949e-418e-ba8a-6dd25571b860', '5e51052f-d8f3-563e-bfe4-dace14c41475', 'නාසාස්ථි සහ ශංඛක අස්ථි තුළ කෝටරක ඇත.', 'නාසාස්ථි සහ ශංඛක අස්ථි තුළ කෝටරක ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7a6dbb7-76ca-4827-8a9a-f6c36db4e41e', '5e51052f-d8f3-563e-bfe4-dace14c41475', 'කටී චක්‍රය විකසනය වන තෙක් ළදරුවාට හිස සෘජුව තබා ගත නොහැකි ය.', 'කටී චක්‍රය විකසනය වන තෙක් ළදරුවාට හිස සෘජුව තබා ගත නොහැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cb9787ff-0788-509e-bac6-770f069813bd', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 29, '<p>දණිස් කටුව හැර මිනිසාගේ අපර ගාත්‍රයේ ඇති අස්ථි සංඛ්‍යාව</p>', '<p>දණිස් කටුව හැර මිනිසාගේ අපර ගාත්‍රයේ ඇති අස්ථි සංඛ්‍යාව</p>', NULL, 'මිනිසාගේ එක් අපර ගාත්‍රයක (පාදයක) සාමාන්‍යයෙන් අස්ථි 30 ක් ඇත. ඒවා නම්: ඌර්වස්ථිය (1), වක්ත්‍රකය (1), ජංඝාස්ථිය (1), දණිස්කටුව (1), ගුල්ඵ අස්ථි (7), පාදකූර අස්ථි (5), සහ ඇඟිලි පුරුක් (14).<br>මෙහිදී දණිස් කටුව (Patella) හැර ගණනය කළ විට අස්ථි සංඛ්‍යාව 30 - 1 = 29 ක් වේ.', 'මිනිසාගේ එක් අපර ගාත්‍රයක (පාදයක) සාමාන්‍යයෙන් අස්ථි 30 ක් ඇත. ඒවා නම්: ඌර්වස්ථිය (1), වක්ත්‍රකය (1), ජංඝාස්ථිය (1), දණිස්කටුව (1), ගුල්ඵ අස්ථි (7), පාදකූර අස්ථි (5), සහ ඇඟිලි පුරුක් (14).<br>මෙහිදී දණිස් කටුව (Patella) හැර ගණනය කළ විට අස්ථි සංඛ්‍යාව 30 - 1 = 29 ක් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
