INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a05418d-0126-4e2c-baa3-9cae5064b10a', 'e6622278-20db-5cac-9e18-0f423f03785d', 'B සහ D පමණි.', 'B සහ D පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ce666d73-2e6e-4fbb-981f-ba97043ef12a', 'e6622278-20db-5cac-9e18-0f423f03785d', 'A, B සහ C පමණි.', 'A, B සහ C පමණි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('67b311a8-ab19-5049-9125-2dda958291f0', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 33, '<p>DNA විසංගමනයේ ප්‍රධාන පියවර පහත දැක්වේ.<br><br>A - DNA අවක්ෂේපනය<br>B - නියුක්ලියොප්‍රෝටීන සංකීර්ණවල විඝටනය<br>C - අපවිත්‍රකාරක ඉවත් කිරීම<br>D - සෛල ද්‍රවණය<br>E - සමජාතීයකරණය<br><br>ඉහත පියවරවල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', '<p>DNA විසංගමනයේ ප්‍රධාන පියවර පහත දැක්වේ.<br><br>A - DNA අවක්ෂේපනය<br>B - නියුක්ලියොප්‍රෝටීන සංකීර්ණවල විඝටනය<br>C - අපවිත්‍රකාරක ඉවත් කිරීම<br>D - සෛල ද්‍රවණය<br>E - සමජාතීයකරණය<br><br>ඉහත පියවරවල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', NULL, 'සෛලයකින් DNA විසංගමනය කිරීමේ (DNA Extraction) සම්මත පියවර අනුපිළිවෙළ මෙසේය:<br>1. සෛල හා පටක සමජාතීයකරණය (E)<br>2. සෛල ද්‍රවණය කිරීම මගින් සෛල බිඳීම (D)<br>3. නියුක්ලියොප්‍රෝටීන සංකීර්ණ විඝටනය කර DNA නිදහස් කිරීම (B)<br>4. ප්‍රෝටීන, RNA වැනි අපවිත්‍රකාරක ඉවත් කිරීම (C)<br>5. අවසාන වශයෙන් මධ්‍යසාර යොදා DNA අවක්ෂේපනය (A).<br>එබැවින් නිවැරදි අනුපිළිවෙළ E, D, B, C, A වේ.', 'සෛලයකින් DNA විසංගමනය කිරීමේ (DNA Extraction) සම්මත පියවර අනුපිළිවෙළ මෙසේය:<br>1. සෛල හා පටක සමජාතීයකරණය (E)<br>2. සෛල ද්‍රවණය කිරීම මගින් සෛල බිඳීම (D)<br>3. නියුක්ලියොප්‍රෝටීන සංකීර්ණ විඝටනය කර DNA නිදහස් කිරීම (B)<br>4. ප්‍රෝටීන, RNA වැනි අපවිත්‍රකාරක ඉවත් කිරීම (C)<br>5. අවසාන වශයෙන් මධ්‍යසාර යොදා DNA අවක්ෂේපනය (A).<br>එබැවින් නිවැරදි අනුපිළිවෙළ E, D, B, C, A වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
