INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5e9d0c02-dc66-4127-92c8-0991db64dabc', '6ccfcb99-d63a-5053-b077-5d8e2a781b5b', 'සැවානා, කාන්තාර, සෞම්‍ය කලාපික තෘණ භූමි, උතුරු කේතුධර වනාන්තර සහ තුන්ද්‍රා වේ.', 'සැවානා, කාන්තාර, සෞම්‍ය කලාපික තෘණ භූමි, උතුරු කේතුධර වනාන්තර සහ තුන්ද්‍රා වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c08d802b-badb-5d18-9ac8-9bd7807a734a', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 35, '<p>ශ්‍රී ලංකාවේ ආක්‍රමණික ආගන්තුක ජීවීන් දෙදෙනෙකු වන්නේ</p>', '<p>ශ්‍රී ලංකාවේ ආක්‍රමණික ආගන්තුක ජීවීන් දෙදෙනෙකු වන්නේ</p>', NULL, 'ගඳපාන (Lantana camara) සහ ජපන් ජබර (Eichhornia crassipes) යනු ශ්‍රී ලංකාවේ පරිසර පද්ධතිවලට දැඩි තර්ජනයක් එල්ල කර ඇති ප්‍රධාන ආක්‍රමණික ආගන්තුක විශේෂ (Invasive Alien Species) දෙකකි.<br>මානා, ඉළුක් යනු දේශීය ශාක විශේෂ වේ.', 'ගඳපාන (Lantana camara) සහ ජපන් ජබර (Eichhornia crassipes) යනු ශ්‍රී ලංකාවේ පරිසර පද්ධතිවලට දැඩි තර්ජනයක් එල්ල කර ඇති ප්‍රධාන ආක්‍රමණික ආගන්තුක විශේෂ (Invasive Alien Species) දෙකකි.<br>මානා, ඉළුක් යනු දේශීය ශාක විශේෂ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
