INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('159b0af9-4ccd-44b7-8c37-06e4292a486d', 'c08d802b-badb-5d18-9ac8-9bd7807a734a', 'ගිනි අන්දර සහ පිනි බර තණ ය.', 'ගිනි අන්දර සහ පිනි බර තණ ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('748ddb21-7c1e-4d7b-b0ce-a1329cbb92a3', 'c08d802b-badb-5d18-9ac8-9bd7807a734a', 'ගඳපාන සහ ජපන් ජබර ය.', 'ගඳපාන සහ ජපන් ජබර ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9b34134a-c62c-5c4b-aab1-840c6a96b3f2', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 36, '<p>වයිරොයිඩ සහ ප්‍රියෝන පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ මොනවාද?<br><br>A - Creutzfeldt-Jakob disease යනු ප්‍රියෝන මගින් මිනිසාට ඇති කරනු ලබන රෝගයකි.<br>B - ධාරක ශාක සෛල තුළ ගුණනය වීම සඳහා අවශ්‍ය සංඥා වයිරොයිඩ දරයි.<br>C - ආරක්ෂක ප්‍රෝටීන ආවරණයකින් වටවූ කෙටි DNA කොටසක් වයිරොයිඩවල ඇත.<br>D - ප්‍රියෝනවල ඇති න්‍යෂ්ටික අම්ල ධාරක ජානවල ආධාරයෙන් ප්‍රතිවලිත වේ.</p>', '<p>වයිරොයිඩ සහ ප්‍රියෝන පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ මොනවාද?<br><br>A - Creutzfeldt-Jakob disease යනු ප්‍රියෝන මගින් මිනිසාට ඇති කරනු ලබන රෝගයකි.<br>B - ධාරක ශාක සෛල තුළ ගුණනය වීම සඳහා අවශ්‍ය සංඥා වයිරොයිඩ දරයි.<br>C - ආරක්ෂක ප්‍රෝටීන ආවරණයකින් වටවූ කෙටි DNA කොටසක් වයිරොයිඩවල ඇත.<br>D - ප්‍රියෝනවල ඇති න්‍යෂ්ටික අම්ල ධාරක ජානවල ආධාරයෙන් ප්‍රතිවලිත වේ.</p>', NULL, 'A ප්‍රකාශය නිවැරදිය: Creutzfeldt-Jakob රෝගය මිනිසාට වැළඳෙන ප්‍රියෝන (Prions) රෝගයකි.<br>B ප්‍රකාශය නිවැරදිය: වයිරොයිඩ යනු ප්‍රෝටීන කේතනය නොකරන, නමුත් ධාරක සෛලයේ එන්සයිම මගින් ප්‍රතිවලිත වීම සඳහා සංඥා සපයන කුඩා RNA අණු වේ.<br>C සහ D වැරදිය: වයිරොයිඩවල ප්‍රෝටීන ආවරණයක් හෝ DNA නොමැති අතර, ප්‍රියෝන යනු ආසාදිත ප්‍රෝටීන පමණක් වන බැවින් ඒවායේ න්‍යෂ්ටික අම්ල කිසිවක් අඩංගු නොවේ.', 'A ප්‍රකාශය නිවැරදිය: Creutzfeldt-Jakob රෝගය මිනිසාට වැළඳෙන ප්‍රියෝන (Prions) රෝගයකි.<br>B ප්‍රකාශය නිවැරදිය: වයිරොයිඩ යනු ප්‍රෝටීන කේතනය නොකරන, නමුත් ධාරක සෛලයේ එන්සයිම මගින් ප්‍රතිවලිත වීම සඳහා සංඥා සපයන කුඩා RNA අණු වේ.<br>C සහ D වැරදිය: වයිරොයිඩවල ප්‍රෝටීන ආවරණයක් හෝ DNA නොමැති අතර, ප්‍රියෝන යනු ආසාදිත ප්‍රෝටීන පමණක් වන බැවින් ඒවායේ න්‍යෂ්ටික අම්ල කිසිවක් අඩංගු නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
