INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dd7b4d6b-744a-42bb-8137-da0d84ea4487', 'e7cd8471-e26b-58cc-84b5-ae9ace82420b', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදිය.', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදිය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4a6fff36-a31e-56b7-9ca3-7cba51e0728b', 'f7c0bf41-a89e-51b8-8999-5ec75aa444dd', 49, '<p>ශ්‍රී ලංකාවේ ඉහළම උන්නතාංශ වල දැකිය හැකි ශාක විශේෂ දෙකක් වන්නේ<br><br>(A) Cymbopogan nardus සහ Themeda tremula.<br>(B) Eleocarpus montanus සහ Mesua ferrea<br>(C) Chrysopogan nodulibarbis සහ Callophyllum walkeri.<br>(D) Cinnamomum ovalifolium සහ Arundinella villosa<br>(E) Terminalia chebula සහ Imperata cylindrica</p>', '<p>ශ්‍රී ලංකාවේ ඉහළම උන්නතාංශ වල දැකිය හැකි ශාක විශේෂ දෙකක් වන්නේ<br><br>(A) Cymbopogan nardus සහ Themeda tremula.<br>(B) Eleocarpus montanus සහ Mesua ferrea<br>(C) Chrysopogan nodulibarbis සහ Callophyllum walkeri.<br>(D) Cinnamomum ovalifolium සහ Arundinella villosa<br>(E) Terminalia chebula සහ Imperata cylindrica</p>', NULL, 'ශ්‍රී ලංකාවේ ඉහළ උන්නතාංශ (කඳුකර ප්‍රදේශ) වල පිහිටි කඳුකර වනාන්තර සහ පතන තෘණ භූමිවල Calophyllum walkeri (කීන), Cinnamomum ovalifolium, Chrysopogan nodulibarbis, සහ Arundinella villosa වැනි ශාක විශේෂ දක්නට ලැබේ. එබැවින් (C) සහ (D) නිවැරදිය.', 'ශ්‍රී ලංකාවේ ඉහළ උන්නතාංශ (කඳුකර ප්‍රදේශ) වල පිහිටි කඳුකර වනාන්තර සහ පතන තෘණ භූමිවල Calophyllum walkeri (කීන), Cinnamomum ovalifolium, Chrysopogan nodulibarbis, සහ Arundinella villosa වැනි ශාක විශේෂ දක්නට ලැබේ. එබැවින් (C) සහ (D) නිවැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode