INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9edc291a-452a-4b57-b275-e04dd301e9d4', '8adae8f9-fd27-5e0c-81ea-dd35e7b95850', 'L1 නිහිත මතකය, L2 නිහිත මතකය, රෙජිස්තර, ප්‍රධාන මතකය, දෘඪ ඩිස්කය', 'L1 නිහිත මතකය, L2 නිහිත මතකය, රෙජිස්තර, ප්‍රධාන මතකය, දෘඪ ඩිස්කය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('96ecf31c-b86c-5660-9083-e5dfc30f7009', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 4, '<p>$01010100_2$ සහ $11101001_2$ යන ද්විමය සංඛ්‍යා දෙක අතර බිටු අනුසාරිත (bit-wise) AND සහ බිටු අනුසාරිත OR මෙහෙයුම්වල නිවැරදි ප්‍රතිඵල පිළිවෙළින් දැක්වෙන්නේ පහත කවරක ද?</p>', '<p>$01010100_2$ සහ $11101001_2$ යන ද්විමය සංඛ්‍යා දෙක අතර බිටු අනුසාරිත (bit-wise) AND සහ බිටු අනුසාරිත OR මෙහෙයුම්වල නිවැරදි ප්‍රතිඵල පිළිවෙළින් දැක්වෙන්නේ පහත කවරක ද?</p>', NULL, 'AND මෙහෙයුම: $01010100 \land 11101001 = 01000000$.<br>OR මෙහෙයුම: $01010100 \lor 11101001 = 11111101$.', 'AND මෙහෙයුම: $01010100 \land 11101001 = 01000000$.<br>OR මෙහෙයුම: $01010100 \lor 11101001 = 11111101$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
