INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3bb28b77-c253-5d75-ae6b-71abde19e2bf', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 7, '<p>උපදෙසක යොමුව (address) ෂඩ් දශමය $10f9$ ලෙස පෙනවිණි. එම යොමුව දශමය ආකාරයට කුමක් වේ ද?</p>', '<p>උපදෙසක යොමුව (address) ෂඩ් දශමය $10f9$ ලෙස පෙනවිණි. එම යොමුව දශමය ආකාරයට කුමක් වේ ද?</p>', NULL, '$10f9_{16} = (1 \times 16^3) + (0 \times 16^2) + (15 \times 16^1) + (9 \times 16^0) = 4096 + 0 + 240 + 9 = 4345_{10}$.', '$10f9_{16} = (1 \times 16^3) + (0 \times 16^2) + (15 \times 16^1) + (9 \times 16^0) = 4096 + 0 + 240 + 9 = 4345_{10}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
