INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2524d910-9ed3-5434-9221-7a0018cb5699', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 10, '<p>සුළු කළ බුලිය ප්‍රකාශ වඩාත් සරල පරිපථ ලබා ගැනීමට ඉවහල් වේ.<br>$X+\overline{X}Y$ හි සුළු කළ ප්‍රකාශනයක් වන්නේ පහත කුමක්ද?</p>', '<p>සුළු කළ බුලිය ප්‍රකාශ වඩාත් සරල පරිපථ ලබා ගැනීමට ඉවහල් වේ.<br>$X+\overline{X}Y$ හි සුළු කළ ප්‍රකාශනයක් වන්නේ පහත කුමක්ද?</p>', NULL, 'බූලීය වීජ ගණිතයේ නියමයන්ට අනුව (Rule of Redundancy), $X + \overline{X}Y = X + Y$ ලෙස සුළු වේ.', 'බූලීය වීජ ගණිතයේ නියමයන්ට අනුව (Rule of Redundancy), $X + \overline{X}Y = X + Y$ ලෙස සුළු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
