INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a643fa8f-2809-54e7-acf0-c9d9679c4645', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 13, '<p>පරිගණක මෙහෙයුම් පද්ධතියක කාර්යයක් නොවන්නේ පහත කවරක් ද?</p>', '<p>පරිගණක මෙහෙයුම් පද්ධතියක කාර්යයක් නොවන්නේ පහත කවරක් ද?</p>', NULL, 'විකල්ප 1, 2, 3 සහ 5 මෙහෙයුම් පද්ධතියක මතක කළමනාකරණයට (Memory Management) අයත් අත්‍යවශ්‍ය කාර්යයන් වේ. නමුත් දෘඪ තැටියේ ඇති ද්විමය ගොනුවල භාවිතය/අන්තර්ගතය අධීක්ෂණය කිරීම සාමාන්‍යයෙන් මෙහෙයුම් පද්ධතියේ සෘජු මූලික කාර්යයක් නොවේ.', 'විකල්ප 1, 2, 3 සහ 5 මෙහෙයුම් පද්ධතියක මතක කළමනාකරණයට (Memory Management) අයත් අත්‍යවශ්‍ය කාර්යයන් වේ. නමුත් දෘඪ තැටියේ ඇති ද්විමය ගොනුවල භාවිතය/අන්තර්ගතය අධීක්ෂණය කිරීම සාමාන්‍යයෙන් මෙහෙයුම් පද්ධතියේ සෘජු මූලික කාර්යයක් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('37e87629-e7e6-4ba6-b352-d99129dc6c2a', 'a643fa8f-2809-54e7-acf0-c9d9679c4645', 'ක්‍රියායනයක පිටුවක් (page) සඳහා මතක රාමුවක් (memory frame) තෝරා ගැනීම', 'ක්‍රියායනයක පිටුවක් (page) සඳහා මතක රාමුවක් (memory frame) තෝරා ගැනීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f690794-4064-44ec-acff-5193e383dc11', 'a643fa8f-2809-54e7-acf0-c9d9679c4645', 'නිදහස් (දැනට භාවිතයේ නොමැති) මතක රාමු ලැයිස්තුවක් පවත්වා ගැනීම', 'නිදහස් (දැනට භාවිතයේ නොමැති) මතක රාමු ලැයිස්තුවක් පවත්වා ගැනීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('16a06404-7870-4b8d-a021-ef67383837a3', 'a643fa8f-2809-54e7-acf0-c9d9679c4645', 'එක් එක් ක්‍රියායනය සඳහා පිටු වගුවක් (page table) පවත්වා ගැනීම', 'එක් එක් ක්‍රියායනය සඳහා පිටු වගුවක් (page table) පවත්වා ගැනීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ed37ca7-ab27-478b-b1c9-ee359006cee2', 'a643fa8f-2809-54e7-acf0-c9d9679c4645', 'දෘඪ ඩිස්කයක ඇති ද්විමය ගොනුවල (binary files) භාවිතය අධික්ෂණය කිරීම', 'දෘඪ ඩිස්කයක ඇති ද්විමය ගොනුවල (binary files) භාවිතය අධික්ෂණය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aff5c460-291f-45d1-a040-9ad8b956200e', 'a643fa8f-2809-54e7-acf0-c9d9679c4645', 'ප්‍රධාන මතකය හා දෘඪ ඩිස්කය අතර ක්‍රියායන ප්‍රතිහරණය (swapping)', 'ප්‍රධාන මතකය හා දෘඪ ඩිස්කය අතර ක්‍රියායන ප්‍රතිහරණය (swapping)', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4ada9c78-7625-5098-9f36-ea0ccca9a2ff', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 14, '<p>ඩිස්කයක එක් කාණ්ඩයක විශාලත්වය (block size) 4KB වේ. එම ඩිස්කයේ ගොනු විභාජන වගුවේ (FAT) කොටසක් එක්තරා අවස්ථාවකදී පහත ආකාරයට වේ. එම කොටස මගින් average.py ගොනුවේ කාණ්ඩ ද දැක්වේ.<br><br>FAT දත්ත:<br>200 → 202<br>201 → 200<br>202 → -1<br>203 → 201<br>204 → 205<br><br>average.py ගොනුවේ නාමාවලි තොරතුර සහ average.py ගොනුව සඳහා ඩිස්කයේ වෙන් කර ඇති ඉඩ ප්‍රමාණය පිළිවෙළින් දැක්වෙන්නේ පහත කවරක ද?</p>
