INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cd5cbd91-1a8f-5b14-a201-88ad524422ea', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 19, '<p>ජාල ස්ථලක (topology) සම්බන්ධයෙන් පහත සඳහන් කුමන ප්‍රකාශය නිවැරදී ද?</p>', '<p>ජාල ස්ථලක (topology) සම්බන්ධයෙන් පහත සඳහන් කුමන ප්‍රකාශය නිවැරදී ද?</p>', NULL, 'මුදු ස්ථලකයක (Ring Topology) ප්‍රධාන ලක්ෂණය වන්නේ සෑම නෝඩුවක්ම (node) හරියටම අසල්වැසි නෝඩු දෙකකට පමණක් සම්බන්ධ වීමයි. අනෙකුත් ස්ථලක විස්තර වැරදි ලෙස දක්වා ඇත.', 'මුදු ස්ථලකයක (Ring Topology) ප්‍රධාන ලක්ෂණය වන්නේ සෑම නෝඩුවක්ම (node) හරියටම අසල්වැසි නෝඩු දෙකකට පමණක් සම්බන්ධ වීමයි. අනෙකුත් ස්ථලක විස්තර වැරදි ලෙස දක්වා ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e2e3741-c5ff-4dbf-88c3-435279e511ac', 'cd5cbd91-1a8f-5b14-a201-88ad524422ea', 'බස් ස්ථලකයේදී, සියලූම නෝඩු (nodes) සම්බන්ධ කිරීමට මධ්‍යගත ජාල නාභියක් (hub) භාවිත වේ.', 'බස් ස්ථලකයේදී, සියලූම නෝඩු (nodes) සම්බන්ධ කිරීමට මධ්‍යගත ජාල නාභියක් (hub) භාවිත වේ.', NULL, 'sanitized', 'v1', 0, 1);
