INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('501221c9-450e-591b-87c2-cef8728c65a5', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 26, '<p>කාර්ය බද්ධ නොවන (non-functional) අවශ්‍යතා පද්ධතියක ගුණාත්මක උපලක්ෂණ නිර්ණය කරයි. කාර්ය බද්ධ නොවන අවශ්‍යතාවක් සඳහා උදාහරණයක් වන්නේ පහත සඳහන් කවරක් ද?</p>', '<p>කාර්ය බද්ධ නොවන (non-functional) අවශ්‍යතා පද්ධතියක ගුණාත්මක උපලක්ෂණ නිර්ණය කරයි. කාර්ය බද්ධ නොවන අවශ්‍යතාවක් සඳහා උදාහරණයක් වන්නේ පහත සඳහන් කවරක් ද?</p>', NULL, 'පද්ධතියක ක්‍රියාකාරීත්වයේ කාර්යක්ෂමතාව, වේගය (Performance/Response Time) සහ ආරක්ෂාව වැනි ගුණාත්මක ලක්ෂණ කාර්ය බද්ධ නොවන (Non-functional) අවශ්‍යතා වේ. තත්පර 4ක් ඇතුළත පුරණය වීම ඊට උදාහරණයකි. අනෙකුත් විකල්ප සියල්ල පද්ධතිය කළ යුතු නිශ්චිත කාර්යයන් (Functional Requirements) වේ.', 'පද්ධතියක ක්‍රියාකාරීත්වයේ කාර්යක්ෂමතාව, වේගය (Performance/Response Time) සහ ආරක්ෂාව වැනි ගුණාත්මක ලක්ෂණ කාර්ය බද්ධ නොවන (Non-functional) අවශ්‍යතා වේ. තත්පර 4ක් ඇතුළත පුරණය වීම ඊට උදාහරණයකි. අනෙකුත් විකල්ප සියල්ල පද්ධතිය කළ යුතු නිශ්චිත කාර්යයන් (Functional Requirements) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5fadc916-fdd7-4e47-bb7f-1d79de23bd41', '501221c9-450e-591b-87c2-cef8728c65a5', 'විද්‍යුත් තැපැල් පද්ධතිය පරිශීලකයින්ට ගොනු ඇමිණීමට ඉඩ ලබාදිය යුතු ය.', 'විද්‍යුත් තැපැල් පද්ධතිය පරිශීලකයින්ට ගොනු ඇමිණීමට ඉඩ ලබාදිය යුතු ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2d4659bd-6a05-44ce-b507-1f05df5a19c8', '501221c9-450e-591b-87c2-cef8728c65a5', 'වෙඩි අඩවියේ සෑම පිටුවක්ම තත්පර 4 ක් ඇතුළත පුරණය (load) විය යුතු ය.', 'වෙඩි අඩවියේ සෑම පිටුවක්ම තත්පර 4 ක් ඇතුළත පුරණය (load) විය යුතු ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e56cdcdb-a0d9-4366-b282-03887aa1c933', '501221c9-450e-591b-87c2-cef8728c65a5', 'ප- චාණිජ වෙබ් අඩවියේ පරිපාලකට, ගනුදෙනුකරුවන්ගේ ලැයිස්තුවක් බැලීමට හැකි විය යුතු ය.', 'ප- චාණිජ වෙබ් අඩවියේ පරිපාලකට, ගනුදෙනුකරුවන්ගේ ලැයිස්තුවක් බැලීමට හැකි විය යුතු ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8183717b-5daa-41fd-a643-9e32ee7ffb95', '501221c9-450e-591b-87c2-cef8728c65a5', 'මාර්ගගත බැංකු පද්ධතිය භාවිත කරන්නෙකුට අවසන් ගනුදෙනු බැලීමට හැකි විය යුතු ය.', 'මාර්ගගත බැංකු පද්ධතිය භාවිත කරන්නෙකුට අවසන් ගනුදෙනු බැලීමට හැකි විය යුතු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6d21998b-3d27-4b46-87d5-e965fcf2e10f', '501221c9-450e-591b-87c2-cef8728c65a5', 'ATM යන්ත්‍රය භාවිත කරන්නන්ට රිසිටි පතක් මුද්‍රණය කිරීමට ඉඩ ලබාදිය යුතු ය.', 'ATM යන්ත්‍රය භාවිත කරන්නන්ට රිසිටි පතක් මුද්‍රණය කිරීමට ඉඩ ලබාදිය යුතු ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6fe25cd2-16b0-5619-ba70-7b708358c398', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 27, '<p>දත්ත ගැලීමේ ආකෘතිකරණය පිළිබඳ නිතිරීති අනුව පහත සඳහන් කුමන දත්ත ගැලීම් රූසටහන (DFD) නිවැරදි වන්නේ ද?<br>(සටහන: A - බාහිර භූතාර්ථයක්, B - ක්‍රියාවලියක්, C - දත්ත ගබඩාවක්)</p>', '<p>දත්ත ගැලීමේ ආකෘතිකරණය පිළිබඳ නිතිරීති අනුව පහත සඳහන් කුමන දත්ත ගැලීම් රූසටහන (DFD) නිවැරදි වන්නේ ද?<br>(සටහන: A - බාහිර භූතාර්ථයක්, B - ක්‍රියාවලියක්, C - දත්ත ගබඩාවක්)</p>', NULL, 'DFD රීතිවලට අනුව දත්ත ගබඩාවකට (Data Store - C) හෝ බාහිර භූතාර්ථයකට (External Entity - A) සෘජුව දත්ත හුවමාරු කරගත නොහැක. ඒවා අනිවාර්යයෙන්ම ක්‍රියාවලියක් (Process - 1.0) හරහා සිදුවිය යුතුය. පළමු රූප සටහනේ පමණක් මෙම නීතිය අනුගමනය කර ඇත.', 'DFD රීතිවලට අනුව දත්ත ගබඩාවකට (Data Store - C) හෝ බාහිර භූතාර්ථයකට (External Entity - A) සෘජුව දත්ත හුවමාරු කරගත නොහැක. ඒවා අනිවාර්යයෙන්ම ක්‍රියාවලියක් (Process - 1.0) හරහා සිදුවිය යුතුය. පළමු රූප සටහනේ පමණක් මෙම නීතිය අනුගමනය කර ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
