INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b67868ca-4adc-5489-b9d2-d079b9f830be', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 28, '<p>මෘදුකාංග පරීක්ෂාව සම්බන්ධයෙන් පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක් ද?</p>', '<p>මෘදුකාංග පරීක්ෂාව සම්බන්ධයෙන් පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක් ද?</p>', NULL, 'ප්‍රතිග්‍රහණ (Acceptance) පරීක්ෂාවේදී පරිශීලකයා පද්ධතියේ අභ්‍යන්තර කේතය ගැන නොසලකා එහි ක්‍රියාකාරිත්වය පමණක් පරීක්ෂා කරන බැවින් එය කාලමංජුසා (Black-box) පරීක්ෂා කිරීමේ ක්‍රමවේදයකි.', 'ප්‍රතිග්‍රහණ (Acceptance) පරීක්ෂාවේදී පරිශීලකයා පද්ධතියේ අභ්‍යන්තර කේතය ගැන නොසලකා එහි ක්‍රියාකාරිත්වය පමණක් පරීක්ෂා කරන බැවින් එය කාලමංජුසා (Black-box) පරීක්ෂා කිරීමේ ක්‍රමවේදයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7a4c2d17-1919-4429-bcd8-796d33027366', 'b67868ca-4adc-5489-b9d2-d079b9f830be', 'ඒකාබද්ධ (integration) පරීක්ෂාව සාමාන්‍යයෙන් එකක (unit) පරීක්ෂාවට පෙර සිදු කෙරේ.', 'ඒකාබද්ධ (integration) පරීක්ෂාව සාමාන්‍යයෙන් එකක (unit) පරීක්ෂාවට පෙර සිදු කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b20aa9fa-f598-4b4f-b35e-eeb0566c2fb2', 'b67868ca-4adc-5489-b9d2-d079b9f830be', 'කාලමංජුසා (black-box) පරීක්ෂාවේ ශිල්පීය ක්‍රම සාමාන්‍යයෙන් ප්‍රතිග්‍රහණ (acceptance) පරික්ෂාවේදි භාවිත වේ.', 'කාලමංජුසා (black-box) පරීක්ෂාවේ ශිල්පීය ක්‍රම සාමාන්‍යයෙන් ප්‍රතිග්‍රහණ (acceptance) පරික්ෂාවේදි භාවිත වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('984cc8ff-4210-469b-8277-861087c2418e', 'b67868ca-4adc-5489-b9d2-d079b9f830be', 'ශ්වේත මංජුසා (white-box) පරීක්ෂාවේ දී මෘදුකාංගයක හැසිරීම, පද්ධතියට ලබා දෙන ආදාන මත පමණක් පදනම්ව පරීක්ෂා කෙරේ.', 'ශ්වේත මංජුසා (white-box) පරීක්ෂාවේ දී මෘදුකාංගයක හැසිරීම, පද්ධතියට ලබා දෙන ආදාන මත පමණක් පදනම්ව පරීක්ෂා කෙරේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fdd6b628-a479-4e39-81af-c2c1bf480a01', 'b67868ca-4adc-5489-b9d2-d079b9f830be', 'ඒකක පරීක්ෂාවේදී සම්පූර්ණ පද්ධතියේ ක්‍රියාකාරිත්වය, සමස්තයක් ලෙස පරීක්ෂා කෙරේ.', 'ඒකක පරීක්ෂාවේදී සම්පූර්ණ පද්ධතියේ ක්‍රියාකාරිත්වය, සමස්තයක් ලෙස පරීක්ෂා කෙරේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bd9a2ac2-d7c9-4090-8531-12d3d8667942', 'b67868ca-4adc-5489-b9d2-d079b9f830be', 'පද්ධති (system) පරීක්ෂාව සාමාන්‍යයෙන් සේවාදායක ප්‍රතිග්‍රහණ (user acceptance) පරීක්ෂාවට පසුව සිදු කෙරේ.', 'පද්ධති (system) පරීක්ෂාව සාමාන්‍යයෙන් සේවාදායක ප්‍රතිග්‍රහණ (user acceptance) පරීක්ෂාවට පසුව සිදු කෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e7772d35-ec62-5626-a1a5-bf29a7f16a65', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 29, '<p>පහත දක්වා ඇති සම්බන්ධතා පරිපාටික සටහන (relational schema) සලකා බලන්න:<br>Student (StudentId, StudentName, Address, Gender, DateOfBirth)<br>Study (StudentId, SubjectId, Grade)<br>Subject (SubjectId, SubjectName)<br><br>ශිෂ්‍යයා (Student) සහ විෂය (Subject) භූතාර්ථ අතර සම්බන්ධතාව නිවැරදිව නිරූපණය කිරීම සඳහා පහත සඳහන් කුමන භූතාර්ට සම්බන්ධතා රූපසටහන (ER diagram) වඩාත් සුදුසු වේ ද?</p>', '<p>පහත දක්වා ඇති සම්බන්ධතා පරිපාටික සටහන (relational schema) සලකා බලන්න:<br>Student (StudentId, StudentName, Address, Gender, DateOfBirth)<br>Study (StudentId, SubjectId, Grade)<br>Subject (SubjectId, SubjectName)<br><br>ශිෂ්‍යයා (Student) සහ විෂය (Subject) භූතාර්ථ අතර සම්බන්ධතාව නිවැරදිව නිරූපණය කිරීම සඳහා පහත සඳහන් කුමන භූතාර්ට සම්බන්ධතා රූපසටහන (ER diagram) වඩාත් සුදුසු වේ ද?</p>', NULL, 'දී ඇති Relational Schema අනුව, `Study` යනු `StudentId` සහ `SubjectId` යන දෙකම අඩංගු අතරමැදි සම්බන්ධතා වගුවකි (Associative entity). මෙයින් නිරූපණය වන්නේ Student සහ Subject අතර පවතින්නේ බොහෝ දෙනෙකු බොහෝ දෙනෙකුට සම්බන්ධ වන (Many-to-Many / n:m) සම්බන්ධතාවක් බවයි.', 'දී ඇති Relational Schema අනුව, `Study` යනු `StudentId` සහ `SubjectId` යන දෙකම අඩංගු අතරමැදි සම්බන්ධතා වගුවකි (Associative entity). මෙයින් නිරූපණය වන්නේ Student සහ Subject අතර පවතින්නේ බොහෝ දෙනෙකු බොහෝ දෙනෙකුට සම්බන්ධ වන (Many-to-Many / n:m) සම්බන්ධතාවක් බවයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
