INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c247b71-f6be-580d-920a-67cdf4d96fbf', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 31, '<p>පහත SQL ප්‍රකාශය ක්‍රියාත්මක කිරීමෙන් පසු ප්‍රතිදානය කුමක් වේ ද?<br>SELECT Customer. Fname, Customer. Lname, Order. OrderId<br>FROM Customer INNER JOIN Order ON Customer. CusId = Order. CusId<br>WHERE Customer.Location="Galle";</p>', '<p>පහත SQL ප්‍රකාශය ක්‍රියාත්මක කිරීමෙන් පසු ප්‍රතිදානය කුමක් වේ ද?<br>SELECT Customer. Fname, Customer. Lname, Order. OrderId<br>FROM Customer INNER JOIN Order ON Customer. CusId = Order. CusId<br>WHERE Customer.Location="Galle";</p>', NULL, 'Location = "Galle" වන පාරිභෝගිකයින් වන්නේ C002 (Kalum Gamage) සහ C003 (Shiromi Silva) ය. Order වගුවට අනුව C002 හි ඇණවුම A002 වන අතර C003 හි ඇණවුම A003 වේ. ඒ අනුව ප්‍රතිදානය "Kalum Gamage A002" සහ "Shiromi Silva A003" වේ.', 'Location = "Galle" වන පාරිභෝගිකයින් වන්නේ C002 (Kalum Gamage) සහ C003 (Shiromi Silva) ය. Order වගුවට අනුව C002 හි ඇණවුම A002 වන අතර C003 හි ඇණවුම A003 වේ. ඒ අනුව ප්‍රතිදානය "Kalum Gamage A002" සහ "Shiromi Silva A003" වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
