INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c855ec69-34f6-544f-8914-c8aa5306ed0b', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 32, '<p>Order වගුව සැලකීමේදී පහත සඳහන් කුමක් නිවැරදි ද?</p>', '<p>Order වගුව සැලකීමේදී පහත සඳහන් කුමක් නිවැරදි ද?</p>', NULL, 'Order වගුවේ ප්‍රාථමික යතුර `OrderId` (තනි උපලක්ෂණයක්) වේ. එහි අර්ධ පරායත්තතාවයක් (Partial dependency) නොමැති බැවින් එය 2NF හි පවතී.', 'Order වගුවේ ප්‍රාථමික යතුර `OrderId` (තනි උපලක්ෂණයක්) වේ. එහි අර්ධ පරායත්තතාවයක් (Partial dependency) නොමැති බැවින් එය 2NF හි පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e27b1f66-4202-48f9-86e2-2c4a8e14480c', 'c855ec69-34f6-544f-8914-c8aa5306ed0b', 'CusId උපලක්ෂණය (attribute) මගින් වගුවේ එක් එක් උපලැකියාන (tuple) අනන්‍යව හඳුනාගනී.', 'CusId උපලක්ෂණය (attribute) මගින් වගුවේ එක් එක් උපලැකියාන (tuple) අනන්‍යව හඳුනාගනී.', NULL, 'sanitized', 'v1', 0, 1);
