INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('87ceb231-cc47-58d0-8cb1-70067f9274e5', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 37, '<p>පහත දැක්වෙන පයිතන් කේතයේ ආදානය 25 වූ විට, ප්‍රතිදානය කුමක් වේ ද?<br>$$x = int(input())$$<br>$$x=(x\% (x-21))^{**}3$$<br>$$print (x)$$</p>', '<p>පහත දැක්වෙන පයිතන් කේතයේ ආදානය 25 වූ විට, ප්‍රතිදානය කුමක් වේ ද?<br>$$x = int(input())$$<br>$$x=(x\% (x-21))^{**}3$$<br>$$print (x)$$</p>', NULL, 'ආදානය $x=25$ යැයි ගත් විට, $(x-21) = 4$. ඉන්පසු $x \% 4 = 25 \% 4 = 1$. ඉන්පසු $1^3 = 1$ වේ. එබැවින් ප්‍රතිදානය 1 වේ.', 'ආදානය $x=25$ යැයි ගත් විට, $(x-21) = 4$. ඉන්පසු $x \% 4 = 25 \% 4 = 1$. ඉන්පසු $1^3 = 1$ වේ. එබැවින් ප්‍රතිදානය 1 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
