INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0ed0bc67-d081-53ff-854e-3aac98da0c03', 'fd323ca4-fe10-5f04-93ba-2332a1baa439', 44, '<p>පහත දැක්වෙන HTML කේත ඛණ්ඩයේ ප්‍රතිදානය කුමක් වේ ද?<br>&lt;dl&gt;<br>&lt;dt&gt; Vegetable &lt;/dt&gt;<br>&lt;dd&gt; Potato &lt;/dd&gt;<br>&lt;dt&gt; Fruit &lt;/dt&gt;<br>&lt;dd&gt; Orange &lt;/dd&gt;<br>&lt;/dl&gt;</p>', '<p>පහත දැක්වෙන HTML කේත ඛණ්ඩයේ ප්‍රතිදානය කුමක් වේ ද?<br>&lt;dl&gt;<br>&lt;dt&gt; Vegetable &lt;/dt&gt;<br>&lt;dd&gt; Potato &lt;/dd&gt;<br>&lt;dt&gt; Fruit &lt;/dt&gt;<br>&lt;dd&gt; Orange &lt;/dd&gt;<br>&lt;/dl&gt;</p>', NULL, 'HTML Definition List (<dl>) භාවිතයේදී, Term (<dt>) සාමාන්‍ය ලෙස දර්ශනය වන අතර Description (<dd>) ස්වයංක්‍රීයව අභ්‍යන්තරයට ඇදී (indented) දර්ශනය වේ. මෙහිදී Bullet points හෝ අංක දිස් නොවේ.', 'HTML Definition List (<dl>) භාවිතයේදී, Term (<dt>) සාමාන්‍ය ලෙස දර්ශනය වන අතර Description (<dd>) ස්වයංක්‍රීයව අභ්‍යන්තරයට ඇදී (indented) දර්ශනය වේ. මෙහිදී Bullet points හෝ අංක දිස් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
