INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6baa48b0-df8b-4fd6-8fec-c5cc869cc667', 'f854cf1a-6ac3-520b-ae04-0052cc897624', 'ග්ලූකෝස් අණු දෙකක් අතර සිදුවන සංඝනන ප්‍රතික්‍රියාව මගින් නිර්ඔක්සිහාරක සීනි අණුවක් සෑදේ.', 'ග්ලූකෝස් අණු දෙකක් අතර සිදුවන සංඝනන ප්‍රතික්‍රියාව මගින් නිර්ඔක්සිහාරක සීනි අණුවක් සෑදේ.', NULL, 'sanitized', 'v1', 0, 1);
