INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ed8071d1-d715-4293-a513-db500b5b1900', 'f854cf1a-6ac3-520b-ae04-0052cc897624', 'ගැලැක්ටියුරොනික් අම්ලය, ශාකවල ව්‍යුහමය පොලිසැකරයිඩයක තැනුම් ඒකකයයි.', 'ගැලැක්ටියුරොනික් අම්ලය, ශාකවල ව්‍යුහමය පොලිසැකරයිඩයක තැනුම් ඒකකයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e648e5e6-d9c1-49a1-b631-f1f778239188', 'f854cf1a-6ac3-520b-ae04-0052cc897624', 'හෙමිසෙලියුලෝස් යනු ට්‍රයෝස සහ පෙන්ටෝසවලින් තැනුනු ශාකනය වූ පොලිසැකරයිඩයකි.', 'හෙමිසෙලියුලෝස් යනු ට්‍රයෝස සහ පෙන්ටෝසවලින් තැනුනු ශාකනය වූ පොලිසැකරයිඩයකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ede0f823-0848-5722-a6f5-ec96da01581f', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 3, '<p>මයිටොකොන්ඩ්‍රියාවල</p>', '<p>මයිටොකොන්ඩ්‍රියාවල</p>', NULL, 'ඔක්සිකාරක පොස්ෆොරයිලීකරණය සඳහා අවශ්‍ය වන ඉලෙක්ට්‍රෝන පරිවහන දාමයේ එන්සයිම පිහිටන්නේ මයිටොකොන්ඩ්‍රියාවේ ඇතුළු පටලයේ ඇති මියර (cristae) වලය.', 'ඔක්සිකාරක පොස්ෆොරයිලීකරණය සඳහා අවශ්‍ය වන ඉලෙක්ට්‍රෝන පරිවහන දාමයේ එන්සයිම පිහිටන්නේ මයිටොකොන්ඩ්‍රියාවේ ඇතුළු පටලයේ ඇති මියර (cristae) වලය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
