INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a3be3c84-45b0-414c-986b-b662b0a633c1', 'ede0f823-0848-5722-a6f5-ec96da01581f', 'පූරකය තුළදී පයිරුවේට් අණුවක්, $CO_2$ අණු දෙකක් නිදහස් කරමින් ඇසිටයිල් Co-A අණුවක් බවට පත් වේ.', 'පූරකය තුළදී පයිරුවේට් අණුවක්, $CO_2$ අණු දෙකක් නිදහස් කරමින් ඇසිටයිල් Co-A අණුවක් බවට පත් වේ.', NULL, 'sanitized', 'v1', 3, 0);
