INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('788d7050-46f4-574f-936a-277b973abf31', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 11, '<p>ශීර්ෂණයේ මුල් සළකුණු පෙන් වූ සතුන්</p>', '<p>ශීර්ෂණයේ මුල් සළකුණු පෙන් වූ සතුන්</p>', NULL, 'ශීර්ෂණයේ (Cephalization) මුල් සලකුණු පෙන්වන ප්ලැටිහෙල්මින්තේස් වංශිකයින්ට (පැතලි පණුවන්) ප්‍රාථමික මධ්‍ය ස්නායු පද්ධතියක් පවතී.', 'ශීර්ෂණයේ (Cephalization) මුල් සලකුණු පෙන්වන ප්ලැටිහෙල්මින්තේස් වංශිකයින්ට (පැතලි පණුවන්) ප්‍රාථමික මධ්‍ය ස්නායු පද්ධතියක් පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
