INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 13, '<p>ශාකවල විභාජක පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ශාකවල විභාජක පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'පරිචර්මය (Periderm) තැනීම සඳහා වල්ක කැම්බියම නැමැති පාර්ශ්වික විභාජක පටකය සෘජුවම දායක වේ.', 'පරිචර්මය (Periderm) තැනීම සඳහා වල්ක කැම්බියම නැමැති පාර්ශ්වික විභාජක පටකය සෘජුවම දායක වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b788ef56-59c9-45dd-b87f-0be8ef9865ac', 'fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'ද්විතීයික වර්ධනය සඳහා පාර්ශ්වික විභාජක සහ අග්‍රස්ථ විභාජක සහභාගී වේ.', 'ද්විතීයික වර්ධනය සඳහා පාර්ශ්වික විභාජක සහ අග්‍රස්ථ විභාජක සහභාගී වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4fe65fe2-c32e-44b1-a9cb-800f9ba25e5f', 'fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'ප්‍රරෝහ අග්‍රස්ථ විභාජකය මගින් නව සෛල ඇතුළට සහ පිටතට නිපදවනු ලැබේ.', 'ප්‍රරෝහ අග්‍රස්ථ විභාජකය මගින් නව සෛල ඇතුළට සහ පිටතට නිපදවනු ලැබේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7854a54c-c506-4ac8-81f2-fd09ef7b6bf3', 'fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'ඒක බීජපත්‍රී ශාකවල කැඩී බිඳී යන පත්‍ර නැවත වර්ධනය වන්නේ ඒවායේ පාදස්ථයේ ඇති පාර්ශ්වික විභාජකවල ක්‍රියාව නිසාය.', 'ඒක බීජපත්‍රී ශාකවල කැඩී බිඳී යන පත්‍ර නැවත වර්ධනය වන්නේ ඒවායේ පාදස්ථයේ ඇති පාර්ශ්වික විභාජකවල ක්‍රියාව නිසාය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c650e3f-02a3-40c7-ad1c-11ed6a570f99', 'fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'පරිචර්මය තැනීමට පාර්ශ්වික විභාජක දායක වේ.', 'පරිචර්මය තැනීමට පාර්ශ්වික විභාජක දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d9232504-6232-4f2e-8f27-5efe56ba3f2c', 'fc83226d-5b02-54b4-adea-8e590d2ef4f3', 'විභාජක සැම විටම සක්‍රිය ය.', 'විභාජක සැම විටම සක්‍රිය ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5508c097-4a58-56f6-a21d-f90878c2cf89', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 14, '<p>ශාක වල සිදු වන ජල හානිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ශාක වල සිදු වන ජල හානිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'බින්දුදය (Guttation) ඇතිවීම සඳහා ධන ජලස්ථාතික පීඩනයක් වන මූල පීඩනය (Root pressure) අත්‍යවශ්‍ය වේ.', 'බින්දුදය (Guttation) ඇතිවීම සඳහා ධන ජලස්ථාතික පීඩනයක් වන මූල පීඩනය (Root pressure) අත්‍යවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2a96c61c-336d-4bcc-a37a-951d7e82f807', '5508c097-4a58-56f6-a21d-f90878c2cf89', 'බින්දුදය දවස මුළුල්ලේ ම සිදු වේ.', 'බින්දුදය දවස මුළුල්ලේ ම සිදු වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('912a4b8c-6bf9-4b42-8039-394607535cb9', '5508c097-4a58-56f6-a21d-f90878c2cf89', 'සාපේක්ෂ ආර්ද්‍රතාව වැඩි විට උත්ස්වේදන ශීඝ්‍රතාව වැඩි ය.', 'සාපේක්ෂ ආර්ද්‍රතාව වැඩි විට උත්ස්වේදන ශීඝ්‍රතාව වැඩි ය.', NULL, 'sanitized', 'v1', 1, 0);
