INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7b630898-cbfa-591d-b705-b140c9e007ca', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 15, '<p>ශාකවල හරිතක්ෂය, ඌන වර්ධනය සහ පත්‍ර අග්‍රය මිය යෑම සඳහා හේතු වන්නේ පිළිවෙළින් පහත සඳහන් කුමන මූල ද්‍රව්‍යවල ඌනතාවද?</p>', '<p>ශාකවල හරිතක්ෂය, ඌන වර්ධනය සහ පත්‍ර අග්‍රය මිය යෑම සඳහා හේතු වන්නේ පිළිවෙළින් පහත සඳහන් කුමන මූල ද්‍රව්‍යවල ඌනතාවද?</p>', NULL, 'මාකින් පටිපාටියට අනුව (2) පිළිතුර වේ.', 'මාකින් පටිපාටියට අනුව (2) පිළිතුර වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
