INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('513e6bcb-758c-44d2-8eb4-3ffc80e81aa5', 'ff8e7c08-22f5-524f-9489-6af8fbf9fa86', 'බාහිර වාතයේ පීඩනයට සාපේක්ෂව පෙණහැලි තුළ පීඩනය අඩු වීම නිසා ප්‍රශ්වාසය පහසු වේ.', 'බාහිර වාතයේ පීඩනයට සාපේක්ෂව පෙණහැලි තුළ පීඩනය අඩු වීම නිසා ප්‍රශ්වාසය පහසු වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2bea3500-1486-4e02-a5b0-d87e55b851ee', 'ff8e7c08-22f5-524f-9489-6af8fbf9fa86', 'පෙණහැලි පටකයේ ඇති සංවේදක ආශ්වාසයේදී පෙණහැලි ප්‍රමාණයට වඩා ප්‍රසාරණය වීම වැළැක්වීමට දායක වේ.', 'පෙණහැලි පටකයේ ඇති සංවේදක ආශ්වාසයේදී පෙණහැලි ප්‍රමාණයට වඩා ප්‍රසාරණය වීම වැළැක්වීමට දායක වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('125e2762-e014-42ba-8469-fb1dd1042440', 'ff8e7c08-22f5-524f-9489-6af8fbf9fa86', 'ගර්ත ආස්තරණය මත තැවරී ඇති තරලයේ අධික පෘෂ්ඨික ආතතිය නිසා බාහිර ශ්වසනය පහසු වේ.', 'ගර්ත ආස්තරණය මත තැවරී ඇති තරලයේ අධික පෘෂ්ඨික ආතතිය නිසා බාහිර ශ්වසනය පහසු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f65b130-86f6-4bdf-a804-1842215e4337', 'ff8e7c08-22f5-524f-9489-6af8fbf9fa86', 'සංස්ථානික රුධිර කේශනාලිකා ඔස්සේ පටක වලට ගලා එන රුධිරයේ ඇති $CO_2$ හි ආංශික පීඩනය, පටකවල ඇති $CO_2$ වල ආංශික පීඩනයට වඩා වැඩි වීම නිසා අභ්‍යන්තර ශ්වසනය පහසු වේ.', 'සංස්ථානික රුධිර කේශනාලිකා ඔස්සේ පටක වලට ගලා එන රුධිරයේ ඇති $CO_2$ හි ආංශික පීඩනය, පටකවල ඇති $CO_2$ වල ආංශික පීඩනයට වඩා වැඩි වීම නිසා අභ්‍යන්තර ශ්වසනය පහසු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 23, '<p>මිනිස් වෘක්ක පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් වෘක්ක පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'වෘක්ක මගින් එරිත්‍රොපොයිටින් (erythropoietin) හෝමෝනය ශ්‍රාවය කරන අතර එය රතු රුධිරාණු නිපදවීම උත්තේජනය කරයි.', 'වෘක්ක මගින් එරිත්‍රොපොයිටින් (erythropoietin) හෝමෝනය ශ්‍රාවය කරන අතර එය රතු රුධිරාණු නිපදවීම උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('84163f9a-33e7-48b1-8484-8865e24143ed', '92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'වම් වෘක්කය, දකුණු වෘක්කයට වඩා ස්වල්පයක් පහළින් අපර උදර බිත්තිය මත පිහිටයි.', 'වම් වෘක්කය, දකුණු වෘක්කයට වඩා ස්වල්පයක් පහළින් අපර උදර බිත්තිය මත පිහිටයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('40692f30-f4b4-461f-9596-ae4e3fd1119b', '92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'වෘක්කයේ ඇති වෘක්කාණු වැඩි සංඛ්‍යාවක් ජස්ටා මජ්ජාමය වෘක්කාණු වේ.', 'වෘක්කයේ ඇති වෘක්කාණු වැඩි සංඛ්‍යාවක් ජස්ටා මජ්ජාමය වෘක්කාණු වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bf5dc7b8-b757-4951-95ad-dd917f738ad2', '92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'රුධිර පීඩනයේ වෙනස් වීම දැනගත හැකි සංවේදක වෘක්කවල ඇත.', 'රුධිර පීඩනයේ වෙනස් වීම දැනගත හැකි සංවේදක වෘක්කවල ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('543e9820-dc2c-41d1-ae0a-18f6f4b6fe84', '92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'වෘක්කාණු හරහා $H^+$ ප්‍රතිශෝෂණය කිරීම මගින් රුධිර pH අගය යාමනය කිරීමට වෘක්කවලට හැකි ය.', 'වෘක්කාණු හරහා $H^+$ ප්‍රතිශෝෂණය කිරීම මගින් රුධිර pH අගය යාමනය කිරීමට වෘක්කවලට හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a8f017a0-dd90-4b40-b8dc-c2931b46d593', '92987f96-0634-5d87-b6b5-a9e4dbb28d4e', 'රක්තාණු නිපදවීමේදී වෘක්ක කාර්යභාරයක් ඉටු කරයි.', 'රක්තාණු නිපදවීමේදී වෘක්ක කාර්යභාරයක් ඉටු කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f032f112-612a-55bd-b890-de3456d94065', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 24, '<p>රසායනික උපාගමවල උපාගම පැල්ම තුළට ස්නායු සම්ප්‍රේෂක නිදහස් වන්නේ පහත සඳහන් කුමකට ප්‍රතිචාරයක් ලෙස ද?</p>', '<p>රසායනික උපාගමවල උපාගම පැල්ම තුළට ස්නායු සම්ප්‍රේෂක නිදහස් වන්නේ පහත සඳහන් කුමකට ප්‍රතිචාරයක් ලෙස ද?</p>', NULL, 'ක්‍රියාපොටෙන්ෂලයක් පැමිණි විට පූර්ව උපාගම පර්යන්තයට $Ca^{2+}$ අයන ඇතුල්වීම මගින් ස්නායු සම්ප්‍රේෂක නිදහස් වීම උත්තේජනය වේ.', 'ක්‍රියාපොටෙන්ෂලයක් පැමිණි විට පූර්ව උපාගම පර්යන්තයට $Ca^{2+}$ අයන ඇතුල්වීම මගින් ස්නායු සම්ප්‍රේෂක නිදහස් වීම උත්තේජනය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
