INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f2ceda72-613f-57ca-aa73-581bf0f9a239', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 30, '<p>මිනිසාගේ ශංඛක අස්ථියේ දක්නට ලැබෙනුයේ පහත සඳහන් කුමන ප්‍රසරද?</p>', '<p>මිනිසාගේ ශංඛක අස්ථියේ දක්නට ලැබෙනුයේ පහත සඳහන් කුමන ප්‍රසරද?</p>', NULL, 'ශංඛක (Temporal) අස්ථියේ ප්‍රධාන වශයෙන් චූචුකාකාර (Mastoid) සහ කිලාභ (Styloid) ප්‍රසර පිහිටයි.', 'ශංඛක (Temporal) අස්ථියේ ප්‍රධාන වශයෙන් චූචුකාකාර (Mastoid) සහ කිලාභ (Styloid) ප්‍රසර පිහිටයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
