INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d460f6ad-d48f-53ba-9008-41c82e48f70e', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 33, '<p>mRNA අච්චුවක් මත cDNA තැනීමට භාවිත කරනු ලබන එන්සයිමය</p>', '<p>mRNA අච්චුවක් මත cDNA තැනීමට භාවිත කරනු ලබන එන්සයිමය</p>', NULL, 'RNA අච්චුවක් ආධාරයෙන් අනුපූරක DNA (cDNA) සංස්ලේෂණය කරනුයේ Reverse Transcriptase එන්සයිමය මගිනි.', 'RNA අච්චුවක් ආධාරයෙන් අනුපූරක DNA (cDNA) සංස්ලේෂණය කරනුයේ Reverse Transcriptase එන්සයිමය මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
