INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7eaac4db-eba6-550b-ae7a-c55508c56503', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 34, '<p>DNA පිළිසකර කිරීමේදී නියුක්ලියේසවල කාර්යභාරය කුමක්ද?</p>', '<p>DNA පිළිසකර කිරීමේදී නියුක්ලියේසවල කාර්යභාරය කුමක්ද?</p>', NULL, 'නියුක්ලියේස (Nucleases) එන්සයිම මගින් DNA දාමයේ හානි වූ හෝ නොගැලපෙන කොටස් කපා ඉවත් කිරීම සිදු කරයි.', 'නියුක්ලියේස (Nucleases) එන්සයිම මගින් DNA දාමයේ හානි වූ හෝ නොගැලපෙන කොටස් කපා ඉවත් කිරීම සිදු කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('073b81e9-836f-4c25-bb91-caf222c4e22b', '7eaac4db-eba6-550b-ae7a-c55508c56503', 'DNA නියුක්ලියොටයිඩ අතර ඇති H බන්ධන බිඳ හෙළීම', 'DNA නියුක්ලියොටයිඩ අතර ඇති H බන්ධන බිඳ හෙළීම', NULL, 'sanitized', 'v1', 0, 1);
