INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e0e1f1f7-eff9-48c1-901c-2c36d85b2997', '9a0eb971-ef17-53ae-9376-adbb270108bb', 'අධිශීත කිරීම සහ සීනි දැමීමයි.', 'අධිශීත කිරීම සහ සීනි දැමීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1df8e837-2dfd-4b8d-b7e2-c0b02b6efdda', '9a0eb971-ef17-53ae-9376-adbb270108bb', 'විකිරණ භාවිතය සහ තාප පිළියමයි.', 'විකිරණ භාවිතය සහ තාප පිළියමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('82dcb840-5d75-58e9-9b97-8a945e8f2162', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 40, '<p>ප්‍රජාවක් තුළ බරවා රෝගය සම්ප්‍රේෂණය වීම සඳහා බලපාන්නේ පහත සඳහන් ඒවායින් මොනවාද?<br><br>A - වාහකයා සහ මිනිසා හමුවන වාර ගණන<br>B - ආසාදිත මදුරුවා තුළ සිටින මයික්‍රොෆයිලේරියාවන්ගේ ඝනත්වය<br>C - ආසාදනයට ලක් වූ පුද්ගලයන් සංඛ්‍යාව<br>D - වාහකයාගේ ලක්ෂණ</p>', '<p>ප්‍රජාවක් තුළ බරවා රෝගය සම්ප්‍රේෂණය වීම සඳහා බලපාන්නේ පහත සඳහන් ඒවායින් මොනවාද?<br><br>A - වාහකයා සහ මිනිසා හමුවන වාර ගණන<br>B - ආසාදිත මදුරුවා තුළ සිටින මයික්‍රොෆයිලේරියාවන්ගේ ඝනත්වය<br>C - ආසාදනයට ලක් වූ පුද්ගලයන් සංඛ්‍යාව<br>D - වාහකයාගේ ලක්ෂණ</p>', NULL, 'බරවා රෝගය සම්ප්‍රේෂණය සඳහා මදුරු වාහකයාගේ හැසිරීම්, රෝගීන් සංඛ්‍යාව මෙන්ම පරපෝෂිත ඝනත්වය යන සියලුම සාධක බලපායි.', 'බරවා රෝගය සම්ප්‍රේෂණය සඳහා මදුරු වාහකයාගේ හැසිරීම්, රෝගීන් සංඛ්‍යාව මෙන්ම පරපෝෂිත ඝනත්වය යන සියලුම සාධක බලපායි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
