INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('686e24e6-a8bc-50ac-bcb1-0d4ff686161e', 'fe4d09e8-70dd-5a85-acc2-114dcd92b3c5', 44, '<p>B$Rh^+$ රුධිර ගණය සහිත පුද්ගලයකුට රුධිර පාරවිලයනයකදී ලබාගත හැක්කේ පහත සඳහන් කුමන රුධිර ගණය ද?/ ගණ ද?<br><br>(A) B $Rh^-$<br>(B) O $Rh^-$<br>(C) AB $Rh^-$<br>(D) O $Rh^+$<br>(E) AB $Rh^+$</p>', '<p>B$Rh^+$ රුධිර ගණය සහිත පුද්ගලයකුට රුධිර පාරවිලයනයකදී ලබාගත හැක්කේ පහත සඳහන් කුමන රුධිර ගණය ද?/ ගණ ද?<br><br>(A) B $Rh^-$<br>(B) O $Rh^-$<br>(C) AB $Rh^-$<br>(D) O $Rh^+$<br>(E) AB $Rh^+$</p>', NULL, 'මෙය B $Rh^+$ රුධිර ගණය සහිත අයෙකු ලෙස උපකල්පනය කර ඇත. ඔහුට B $Rh^-$, O $Rh^-$ හා O $Rh^+$ රුධිරය ලබාගත හැකි බැවින් (A), (B), (D) නිවැරදිය.', 'මෙය B $Rh^+$ රුධිර ගණය සහිත අයෙකු ලෙස උපකල්පනය කර ඇත. ඔහුට B $Rh^-$, O $Rh^-$ හා O $Rh^+$ රුධිරය ලබාගත හැකි බැවින් (A), (B), (D) නිවැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
